package com.fatelocked;

import com.fatelocked.guardian.travel.TravelBlockNoticeStore;
import org.junit.Test;

import java.awt.Canvas;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class FateLockedTravelBlockOverlayTest
{
    @Test
    public void rendersOnlyForAnActiveNoticeWhileStrictModeIsEnabledAndUnpaused()
    {
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(
            Clock.fixed(Instant.parse("2026-07-24T10:00:00Z"), ZoneOffset.UTC));
        AtomicBoolean enabled = new AtomicBoolean(true);
        AtomicBoolean paused = new AtomicBoolean(false);
        FateLockedTravelBlockOverlay overlay = new FateLockedTravelBlockOverlay(
            store, enabled::get, paused::get, () -> {});

        assertEquals(null, render(overlay));

        store.show("boat:port", "Travel blocked - Boat", "Port is locked", "Varrock tablet");
        Dimension rendered = render(overlay);
        assertNotNull(rendered);
        assertNotNull(overlay.getPauseButtonBounds());

        enabled.set(false);
        assertEquals(null, render(overlay));
        enabled.set(true);
        paused.set(true);
        assertEquals(null, render(overlay));
    }

    @Test
    public void onlyLeftPressInsidePauseButtonInvokesTheSuppliedCallbackAndConsumesTheEvent()
    {
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(
            Clock.fixed(Instant.parse("2026-07-24T10:00:00Z"), ZoneOffset.UTC));
        AtomicInteger pauses = new AtomicInteger();
        FateLockedTravelBlockOverlay overlay = new FateLockedTravelBlockOverlay(
            store, () -> true, () -> false, pauses::incrementAndGet);
        store.show("walk:locked", "Travel blocked - Walk here", "Locked", null);
        render(overlay);

        Rectangle button = overlay.getPauseButtonBounds();
        MouseEvent inside = mouse(MouseEvent.MOUSE_PRESSED,
            button.x + button.width / 2, button.y + button.height / 2, MouseEvent.BUTTON1);
        MouseEvent outside = mouse(MouseEvent.MOUSE_PRESSED,
            button.x - 1, button.y - 1, MouseEvent.BUTTON1);
        MouseEvent rightInside = mouse(MouseEvent.MOUSE_PRESSED,
            button.x + button.width / 2, button.y + button.height / 2, MouseEvent.BUTTON3);

        assertNull(overlay.mousePressed(inside));
        assertEquals(1, pauses.get());
        assertSame(outside, overlay.mousePressed(outside));
        assertSame(rightInside, overlay.mousePressed(rightInside));
        assertEquals(1, pauses.get());
    }

    @Test
    public void pausesForTheVisibleCanvasRelativeButtonAndNotItsOldLocalCoordinates()
    {
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(
            Clock.fixed(Instant.parse("2026-07-24T10:00:00Z"), ZoneOffset.UTC));
        AtomicInteger pauses = new AtomicInteger();
        FateLockedTravelBlockOverlay overlay = new FateLockedTravelBlockOverlay(
            store, () -> true, () -> false, pauses::incrementAndGet);
        overlay.setBounds(new Rectangle(120, 70, 0, 0));
        store.show("walk:locked", "Travel blocked - Walk here", "Locked", null);
        render(overlay);

        Rectangle localButton = overlay.getPauseButtonBounds();
        MouseEvent visibleButton = mouse(MouseEvent.MOUSE_PRESSED,
            120 + localButton.x + localButton.width / 2,
            70 + localButton.y + localButton.height / 2, MouseEvent.BUTTON1);
        MouseEvent oldLocalCoordinates = mouse(MouseEvent.MOUSE_PRESSED,
            localButton.x + localButton.width / 2,
            localButton.y + localButton.height / 2, MouseEvent.BUTTON1);

        assertNull(overlay.mousePressed(visibleButton));
        assertEquals(1, pauses.get());
        assertSame(oldLocalCoordinates, overlay.mousePressed(oldLocalCoordinates));
        assertEquals(1, pauses.get());
    }

    @Test
    public void passesThroughWhenStrictModeIsDisabledAfterRendering()
    {
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(
            Clock.fixed(Instant.parse("2026-07-24T10:00:00Z"), ZoneOffset.UTC));
        AtomicBoolean enabled = new AtomicBoolean(true);
        AtomicInteger pauses = new AtomicInteger();
        FateLockedTravelBlockOverlay overlay = new FateLockedTravelBlockOverlay(
            store, enabled::get, () -> false, pauses::incrementAndGet);
        store.show("walk:locked", "Travel blocked - Walk here", "Locked", null);
        render(overlay);
        MouseEvent click = insideButton(overlay);

        enabled.set(false);

        assertSame(click, overlay.mousePressed(click));
        assertEquals(0, pauses.get());
    }

    @Test
    public void passesThroughWhenStrictModeIsPausedAfterRendering()
    {
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(
            Clock.fixed(Instant.parse("2026-07-24T10:00:00Z"), ZoneOffset.UTC));
        AtomicBoolean paused = new AtomicBoolean(false);
        AtomicInteger pauses = new AtomicInteger();
        FateLockedTravelBlockOverlay overlay = new FateLockedTravelBlockOverlay(
            store, () -> true, paused::get, pauses::incrementAndGet);
        store.show("walk:locked", "Travel blocked - Walk here", "Locked", null);
        render(overlay);
        MouseEvent click = insideButton(overlay);

        paused.set(true);

        assertSame(click, overlay.mousePressed(click));
        assertEquals(0, pauses.get());
    }

    @Test
    public void passesThroughWhenTheNoticeExpiresAfterRendering()
    {
        MutableClock clock = new MutableClock();
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(clock);
        AtomicInteger pauses = new AtomicInteger();
        FateLockedTravelBlockOverlay overlay = new FateLockedTravelBlockOverlay(
            store, () -> true, () -> false, pauses::incrementAndGet);
        store.show("walk:locked", "Travel blocked - Walk here", "Locked", null);
        render(overlay);
        MouseEvent click = insideButton(overlay);

        clock.advance(Duration.ofSeconds(4));

        assertSame(click, overlay.mousePressed(click));
        assertEquals(0, pauses.get());
    }

    @Test
    public void nonPressMouseEventsAlwaysPassThroughUnchanged()
    {
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(
            Clock.fixed(Instant.parse("2026-07-24T10:00:00Z"), ZoneOffset.UTC));
        FateLockedTravelBlockOverlay overlay = new FateLockedTravelBlockOverlay(
            store, () -> true, () -> false, () -> {});
        MouseEvent event = mouse(MouseEvent.MOUSE_MOVED, 4, 5, MouseEvent.NOBUTTON);

        assertSame(event, overlay.mouseClicked(event));
        assertSame(event, overlay.mouseReleased(event));
        assertSame(event, overlay.mouseEntered(event));
        assertSame(event, overlay.mouseExited(event));
        assertSame(event, overlay.mouseDragged(event));
        assertSame(event, overlay.mouseMoved(event));
    }

    private static Dimension render(FateLockedTravelBlockOverlay overlay)
    {
        BufferedImage image = new BufferedImage(500, 250, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try
        {
            return overlay.render(graphics);
        }
        finally
        {
            graphics.dispose();
        }
    }

    private static MouseEvent mouse(int id, int x, int y, int button)
    {
        return new MouseEvent(new Canvas(), id, 0L, 0, x, y, 1, false, button);
    }

    private static MouseEvent insideButton(FateLockedTravelBlockOverlay overlay)
    {
        Rectangle button = overlay.getPauseButtonBounds();
        Rectangle overlayBounds = overlay.getBounds();
        return mouse(MouseEvent.MOUSE_PRESSED,
            overlayBounds.x + button.x + button.width / 2,
            overlayBounds.y + button.y + button.height / 2, MouseEvent.BUTTON1);
    }

    private static final class MutableClock extends Clock
    {
        private Instant now = Instant.parse("2026-07-24T10:00:00Z");

        void advance(Duration duration)
        {
            now = now.plus(duration);
        }

        @Override public ZoneId getZone() { return ZoneOffset.UTC; }
        @Override public Clock withZone(ZoneId zone) { return this; }
        @Override public Instant instant() { return now; }
    }
}

package com.fatelocked;

import com.google.gson.Gson;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import org.junit.Test;

import java.io.InputStream;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.nio.charset.StandardCharsets;
import java.time.Instant;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

public class FateLockedRelayImportTest
{
    private static final String PAIRING_CODE =
        "0123456789abcdef0123456789abcdef";

    @Test
    public void manualPairingCodeIsDetectedBeforeParsingAndRepeatedWarningIsSuppressed()
        throws Exception
    {
        TestPlugin testPlugin = newPlugin();
        FateLockedBundle previous = testPlugin.plugin.getBundle();
        Instant importedAt = Instant.parse("2026-07-27T12:34:56Z");
        setField(testPlugin.plugin, "rulesImportedAt", importedAt);

        assertFalse(applyPastedBundle(
            testPlugin.plugin, PAIRING_CODE, "PASTE"));
        assertFalse(applyPastedBundle(
            testPlugin.plugin, PAIRING_CODE, "CLIPBOARD"));

        assertSame(previous, testPlugin.plugin.getBundle());
        assertSame(importedAt, field(testPlugin.plugin, "rulesImportedAt"));
        verify(testPlugin.panel, times(1)).flashStatus(
            "pairing code detected — use Connect tracker", false);
    }

    @Test
    public void repeatedMalformedImportKeepsPriorSnapshotAndWarnsOnlyOnce()
        throws Exception
    {
        TestPlugin testPlugin = newPlugin();
        FateLockedBundle previous = testPlugin.plugin.getBundle();
        Instant importedAt = Instant.parse("2026-07-27T12:34:56Z");
        setField(testPlugin.plugin, "rulesImportedAt", importedAt);

        assertFalse(applyPastedBundle(testPlugin.plugin, "{bad", "PASTE"));
        assertFalse(applyPastedBundle(
            testPlugin.plugin, "{bad", "CLIPBOARD"));

        assertSame(previous, testPlugin.plugin.getBundle());
        assertSame(importedAt, field(testPlugin.plugin, "rulesImportedAt"));
        verify(testPlugin.panel, times(1)).flashStatus(
            "import failed — using previous rules", false);
    }

    @Test
    public void relayImporterCommitsOnlyStrictV4Bundles() throws Exception
    {
        TestPlugin testPlugin = newPlugin();
        FateLockedBundle previous = testPlugin.plugin.getBundle();
        Instant importedAt = Instant.parse("2026-07-27T12:34:56Z");
        setField(testPlugin.plugin, "rulesImportedAt", importedAt);

        assertFalse(acceptRelayPayload(
            testPlugin.plugin, fixture("bundles/v3-standard.json")));
        assertSame(previous, testPlugin.plugin.getBundle());
        assertSame(importedAt, field(testPlugin.plugin, "rulesImportedAt"));

        assertTrue(acceptRelayPayload(
            testPlugin.plugin, fixture("bundles/v4-rules.json")));
        assertNotNull(field(testPlugin.plugin, "rulesImportedAt"));
        verify(testPlugin.panel, times(1))
            .update(any(FateLockedBundle.class), any());
    }

    @Test
    public void relayImporterRollsBackWhenPanelRefreshFails() throws Exception
    {
        TestPlugin testPlugin = newPlugin();
        FateLockedBundle previous = testPlugin.plugin.getBundle();
        Instant importedAt = Instant.parse("2026-07-27T12:34:56Z");
        setField(testPlugin.plugin, "rulesImportedAt", importedAt);
        doThrow(new IllegalStateException("panel failed"))
            .when(testPlugin.panel)
            .update(any(FateLockedBundle.class), any());

        assertFalse(acceptRelayPayload(
            testPlugin.plugin, fixture("bundles/v4-rules.json")));

        assertSame(previous, testPlugin.plugin.getBundle());
        assertSame(importedAt, field(testPlugin.plugin, "rulesImportedAt"));
        verify(testPlugin.panel, never()).flashStatus(
            org.mockito.ArgumentMatchers.startsWith("synced "), eq(true));
    }

    private static TestPlugin newPlugin() throws Exception
    {
        FateLockedPlugin plugin = new FateLockedPlugin();
        FateLockedPanel panel = mock(FateLockedPanel.class);
        setField(plugin, "client", mock(Client.class));
        setField(plugin, "config", mock(FateLockedConfig.class));
        setField(plugin, "panel", panel);
        setField(plugin, "gson", new Gson());
        setField(plugin, "worldMapPointManager",
            mock(WorldMapPointManager.class));
        return new TestPlugin(plugin, panel);
    }

    private static boolean applyPastedBundle(
        FateLockedPlugin plugin, String value, String sourceName)
        throws Exception
    {
        Class<?> sourceClass = Class.forName(
            FateLockedPlugin.class.getName() + "$ImportSource");
        @SuppressWarnings({"rawtypes", "unchecked"})
        Object source = Enum.valueOf(
            (Class<? extends Enum>) sourceClass, sourceName);
        Method method = FateLockedPlugin.class.getDeclaredMethod(
            "applyPastedBundle", String.class, sourceClass);
        method.setAccessible(true);
        return (Boolean) method.invoke(plugin, value, source);
    }

    private static boolean acceptRelayPayload(
        FateLockedPlugin plugin, String value) throws Exception
    {
        Method method = FateLockedPlugin.class.getDeclaredMethod(
            "acceptRelayPayload", String.class);
        method.setAccessible(true);
        return (Boolean) method.invoke(plugin, value);
    }

    private static Object field(Object target, String name) throws Exception
    {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        return field.get(target);
    }

    private static void setField(
        Object target, String name, Object value) throws Exception
    {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static String fixture(String name) throws Exception
    {
        try (InputStream input =
            FateLockedRelayImportTest.class.getClassLoader()
                .getResourceAsStream(name))
        {
            assertNotNull("missing fixture " + name, input);
            return new String(
                input.readAllBytes(), StandardCharsets.UTF_8);
        }
    }

    private static final class TestPlugin
    {
        private final FateLockedPlugin plugin;
        private final FateLockedPanel panel;

        private TestPlugin(
            FateLockedPlugin plugin, FateLockedPanel panel)
        {
            this.plugin = plugin;
            this.panel = panel;
        }
    }
}

package com.fatelocked;

import com.fatelocked.guardian.GuardedActionFactory;
import com.fatelocked.guardian.StrictModeClickHandler;
import com.fatelocked.guardian.StrictModeGuard;
import com.fatelocked.guardian.travel.TravelActionResolver;
import com.fatelocked.guardian.travel.TravelAlternativeFinder;
import com.fatelocked.guardian.travel.TravelAvailability;
import com.fatelocked.guardian.travel.TravelBlockNoticeStore;
import com.fatelocked.guardian.travel.TravelGuardianCoordinator;
import com.fatelocked.guardian.travel.TravelRuleEvaluator;
import com.google.gson.Gson;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;
import org.junit.Test;

import java.io.InputStream;
import java.lang.reflect.Field;
import java.nio.charset.StandardCharsets;
import java.time.Clock;
import java.time.Instant;
import java.util.Optional;

import static org.junit.Assert.assertFalse;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class FateLockedPluginTravelAccountBindingTest
{
    @Test
    public void missingRulesAccountCannotEnforceOrSuggest() throws Exception
    {
        assertUnboundFailsOpen(lockedBundle().replace(
            "\"account\": \"Nubles\",", ""), true, "Nubles");
    }

    @Test
    public void blankRulesAccountCannotEnforceOrSuggest() throws Exception
    {
        assertUnboundFailsOpen(lockedBundle().replace(
            "\"account\": \"Nubles\"", "\"account\": \"   \""),
            true, "Nubles");
    }

    @Test
    public void absentLocalPlayerCannotEnforceOrSuggest() throws Exception
    {
        assertUnboundFailsOpen(lockedBundle(), false, null);
    }

    @Test
    public void wrongLocalPlayerCannotEnforceOrSuggest() throws Exception
    {
        assertUnboundFailsOpen(lockedBundle(), true, "Other Player");
    }

    @Test
    public void unboundRulesWithAbsentPlayerRetainGenericEquipmentEnforcement()
        throws Exception
    {
        Harness harness = new Harness(lockedBundle().replace(
            "\"account\": \"Nubles\"," , ""), false, null);
        MenuEntry entry = mock(MenuEntry.class);
        when(entry.getOption()).thenReturn("Wield");
        when(entry.getTarget()).thenReturn("Abyssal whip");
        when(entry.getType()).thenReturn(MenuAction.UNKNOWN);
        when(entry.getItemId()).thenReturn(4151);
        MenuOptionClicked click = mock(MenuOptionClicked.class);
        when(click.getMenuEntry()).thenReturn(entry);

        harness.plugin.onMenuOptionClicked(click);

        verify(click).consume();
    }
    @Test
    public void normalizedMatchingAccountCanEnforceAndLookUpAlternatives()
        throws Exception
    {
        Harness harness = new Harness(lockedBundle(), true, "nUbLeS");
        MenuOptionClicked click = namedTeleportClick();

        harness.plugin.onMenuOptionClicked(click);

        verify(click).consume();
        verify(harness.finder).find(any(), any(), any());
    }

    private static void assertUnboundFailsOpen(
        String json, boolean playerPresent, String playerName) throws Exception
    {
        Harness harness = new Harness(json, playerPresent, playerName);
        MenuOptionClicked click = namedTeleportClick();

        harness.plugin.onMenuOptionClicked(click);

        verify(click, never()).consume();
        verify(harness.finder, never()).find(any(), any(), any());
        assertFalse(harness.noticeStore.current().isPresent());
    }

    private static MenuOptionClicked namedTeleportClick()
    {
        MenuEntry entry = mock(MenuEntry.class);
        when(entry.getOption()).thenReturn("Teleport");
        when(entry.getTarget()).thenReturn("Lumbridge");
        when(entry.getType()).thenReturn(MenuAction.UNKNOWN);
        MenuOptionClicked click = mock(MenuOptionClicked.class);
        when(click.getMenuEntry()).thenReturn(entry);
        return click;
    }

    private static String lockedBundle() throws Exception
    {
        return fixtureText("bundles/v4-rules.json")
            .replace("\"entry\": \"ALLOWED\"", "\"entry\": \"LOCKED\"");
    }

    private static String fixtureText(String name) throws Exception
    {
        try (InputStream in =
            FateLockedPluginTravelAccountBindingTest.class.getClassLoader()
                .getResourceAsStream(name))
        {
            return new String(in.readAllBytes(), StandardCharsets.UTF_8);
        }
    }

    private static void setField(Object target, String name, Object value)
        throws Exception
    {
        Field field = FateLockedPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static final class Harness
    {
        private final FateLockedPlugin plugin = new FateLockedPlugin();
        private final TravelAlternativeFinder finder =
            mock(TravelAlternativeFinder.class);
        private final TravelBlockNoticeStore noticeStore =
            new TravelBlockNoticeStore(Clock.systemUTC());

        private Harness(
            String json, boolean playerPresent, String playerName)
            throws Exception
        {
            Gson gson = new Gson();
            FateLockedBundle bundle = FateLockedBundle.loadFromJson(gson, json);
            FateLockedConfig config = mock(FateLockedConfig.class);
            when(config.strictMode()).thenReturn(true);

            Client client = mock(Client.class);
            if (playerPresent)
            {
                Player player = mock(Player.class);
                when(client.getLocalPlayer()).thenReturn(player);
                when(player.getName()).thenReturn(playerName);
                when(player.getWorldLocation()).thenReturn(
                    new WorldPoint(49 << 6, 50 << 6, 0));
            }

            TravelAvailability availability = mock(TravelAvailability.class);
            when(finder.find(any(), any(), any())).thenReturn(Optional.empty());
            TravelGuardianCoordinator coordinator =
                new TravelGuardianCoordinator(
                    new TravelActionResolver(),
                    new TravelRuleEvaluator(),
                    finder,
                    noticeStore,
                    new StrictModeClickHandler(new StrictModeGuard()));
            GuardedActionFactory genericFactory = new GuardedActionFactory();
            StrictModeClickHandler genericClickHandler =
                new StrictModeClickHandler(new StrictModeGuard());
            TravelGuardianPluginShell shell = new TravelGuardianPluginShell(
                coordinator,
                availability,
                message -> { },
                entry -> { },
                (event, context) -> genericClickHandler.handle(
                    event, genericFactory.from(event.getMenuEntry(), client), context),
                (stage, error) -> { },
                Clock.systemUTC());

            setField(plugin, "bundle", bundle);
            setField(plugin, "config", config);
            setField(plugin, "client", client);
            TrackerConnectionSettings connectionSettings =
                mock(TrackerConnectionSettings.class);
            when(connectionSettings.isPaired()).thenReturn(true);
            when(connectionSettings.networkAccessAllowed()).thenReturn(true);
            TrackerConnectionController connectionController =
                mock(TrackerConnectionController.class);
            when(connectionController.snapshot()).thenReturn(
                TrackerConnectionSnapshot.connected(Instant.now(), "1"));
            setField(plugin, "connectionSettings", connectionSettings);
            setField(plugin, "connectionController", connectionController);
            setField(plugin, "travelGuardianShell", shell);
        }
    }
}

package com.fatelocked;

import org.junit.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class TravelGuardianOverlayLifecycleTest
{
    @Test
    public void addMutationFailureIsRolledBackAndSuccessfulRollbackClearsResponsibility()
    {
        RecordingOperations operations = new RecordingOperations();
        operations.failAdd = true;
        TravelGuardianOverlayLifecycle lifecycle = operations.lifecycle();

        IllegalStateException failure = assertThrows(
            IllegalStateException.class, lifecycle::start);

        assertEquals("add", failure.getMessage());
        assertEquals(0, failure.getSuppressed().length);
        assertFalse(operations.overlayPresent);
        assertEquals(Arrays.asList("add", "remove"), operations.calls);

        lifecycle.stop();
        assertEquals(Arrays.asList("add", "remove"), operations.calls);
    }

    @Test
    public void addMutationFailureKeepsFailedRollbackRetryable()
    {
        RecordingOperations operations = new RecordingOperations();
        operations.failAdd = true;
        operations.failRemove = true;
        TravelGuardianOverlayLifecycle lifecycle = operations.lifecycle();

        IllegalStateException failure = assertThrows(
            IllegalStateException.class, lifecycle::start);

        assertEquals("add", failure.getMessage());
        assertEquals(1, failure.getSuppressed().length);
        assertEquals("remove", failure.getSuppressed()[0].getMessage());
        assertTrue(operations.overlayPresent);
        assertEquals(Arrays.asList("add", "remove"), operations.calls);

        operations.failRemove = false;
        lifecycle.stop();
        lifecycle.stop();

        assertFalse(operations.overlayPresent);
        assertEquals(Arrays.asList("add", "remove", "remove"),
            operations.calls);
    }

    @Test
    public void registrationMutationFailureRollsBackMouseAndOverlay()
    {
        RecordingOperations operations = new RecordingOperations();
        operations.failRegister = true;
        TravelGuardianOverlayLifecycle lifecycle = operations.lifecycle();

        IllegalStateException failure = assertThrows(
            IllegalStateException.class, lifecycle::start);

        assertEquals("register", failure.getMessage());
        assertEquals(0, failure.getSuppressed().length);
        assertFalse(operations.mousePresent);
        assertFalse(operations.overlayPresent);
        assertEquals(Arrays.asList("add", "register", "unregister", "remove"),
            operations.calls);

        lifecycle.stop();
        assertEquals(Arrays.asList("add", "register", "unregister", "remove"),
            operations.calls);
    }

    @Test
    public void registrationMutationFailureKeepsEachFailedCleanupRetryable()
    {
        RecordingOperations operations = new RecordingOperations();
        operations.failRegister = true;
        operations.failUnregister = true;
        operations.failRemove = true;
        TravelGuardianOverlayLifecycle lifecycle = operations.lifecycle();

        IllegalStateException failure = assertThrows(
            IllegalStateException.class, lifecycle::start);

        assertEquals("register", failure.getMessage());
        assertEquals(2, failure.getSuppressed().length);
        assertEquals("unregister", failure.getSuppressed()[0].getMessage());
        assertEquals("remove", failure.getSuppressed()[1].getMessage());
        assertTrue(operations.mousePresent);
        assertTrue(operations.overlayPresent);
        assertEquals(Arrays.asList("add", "register", "unregister", "remove"),
            operations.calls);

        operations.failUnregister = false;
        operations.failRemove = false;
        lifecycle.stop();
        lifecycle.stop();

        assertFalse(operations.mousePresent);
        assertFalse(operations.overlayPresent);
        assertEquals(Arrays.asList(
            "add", "register", "unregister", "remove",
            "unregister", "remove"), operations.calls);
    }

    @Test
    public void unregisterFailureStillRemovesTheOverlay()
    {
        RecordingOperations operations = new RecordingOperations();
        TravelGuardianOverlayLifecycle lifecycle = operations.lifecycle();
        lifecycle.start();
        operations.failUnregister = true;

        assertThrows(IllegalStateException.class, lifecycle::stop);

        assertEquals(Arrays.asList(
            "add", "register", "unregister", "remove"), operations.calls);
    }

    @Test
    public void partialShutdownCanBeRetriedWithoutRepeatingSuccessfulCleanup()
    {
        RecordingOperations operations = new RecordingOperations();
        TravelGuardianOverlayLifecycle lifecycle = operations.lifecycle();
        lifecycle.start();
        operations.failUnregister = true;
        operations.failRemove = true;
        assertThrows(IllegalStateException.class, lifecycle::stop);

        operations.failUnregister = false;
        operations.failRemove = false;
        lifecycle.stop();
        lifecycle.stop();

        assertEquals(Arrays.asList(
            "add", "register",
            "unregister", "remove",
            "unregister", "remove"), operations.calls);
    }

    @Test
    public void normalLifecycleIsSymmetricAndIdempotent()
    {
        RecordingOperations operations = new RecordingOperations();
        TravelGuardianOverlayLifecycle lifecycle = operations.lifecycle();

        lifecycle.start();
        lifecycle.start();
        lifecycle.stop();
        lifecycle.stop();

        assertFalse(operations.mousePresent);
        assertFalse(operations.overlayPresent);
        assertEquals(Arrays.asList(
            "add", "register", "unregister", "remove"), operations.calls);
    }

    private static final class RecordingOperations
    {
        private final List<String> calls = new ArrayList<>();
        private boolean failAdd;
        private boolean failRegister;
        private boolean failUnregister;
        private boolean failRemove;
        private boolean overlayPresent;
        private boolean mousePresent;

        private TravelGuardianOverlayLifecycle lifecycle()
        {
            return new TravelGuardianOverlayLifecycle(
                () -> {
                    calls.add("add");
                    overlayPresent = true;
                    if (failAdd)
                    {
                        throw new IllegalStateException("add");
                    }
                },
                () -> {
                    calls.add("register");
                    mousePresent = true;
                    if (failRegister)
                    {
                        throw new IllegalStateException("register");
                    }
                },
                () -> {
                    calls.add("unregister");
                    if (failUnregister)
                    {
                        throw new IllegalStateException("unregister");
                    }
                    mousePresent = false;
                },
                () -> {
                    calls.add("remove");
                    if (failRemove)
                    {
                        throw new IllegalStateException("remove");
                    }
                    overlayPresent = false;
                });
        }
    }
}

package com.fatelocked;

import org.junit.Test;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class RepeatedValueLimiterTest
{
    private static final long THIRTY_SECONDS = 30_000L;

    @Test
    public void reportsTheFirstValue()
    {
        RepeatedValueLimiter limiter =
            new RepeatedValueLimiter(THIRTY_SECONDS);

        assertTrue(limiter.shouldReport("first", 1_000L));
    }

    @Test
    public void suppressesTheSameValueInsideTheWindow()
    {
        RepeatedValueLimiter limiter =
            new RepeatedValueLimiter(THIRTY_SECONDS);

        assertTrue(limiter.shouldReport("first", 1_000L));
        assertFalse(limiter.shouldReport("first", 30_999L));
    }

    @Test
    public void reportsADifferentValueImmediately()
    {
        RepeatedValueLimiter limiter =
            new RepeatedValueLimiter(THIRTY_SECONDS);

        assertTrue(limiter.shouldReport("first", 1_000L));
        assertTrue(limiter.shouldReport("different", 2_000L));
    }

    @Test
    public void reportsTheSameValueAtTheWindowBoundary()
    {
        RepeatedValueLimiter limiter =
            new RepeatedValueLimiter(THIRTY_SECONDS);

        assertTrue(limiter.shouldReport("first", 1_000L));
        assertTrue(limiter.shouldReport("first", 31_000L));
    }

    @Test
    public void reportsAConcurrentIdenticalValueOnlyOnce() throws Exception
    {
        int callers = 16;
        ExecutorService executor = Executors.newFixedThreadPool(callers);
        try
        {
            for (int round = 0; round < 100; round++)
            {
                RepeatedValueLimiter limiter =
                    new RepeatedValueLimiter(THIRTY_SECONDS);
                CountDownLatch ready = new CountDownLatch(callers);
                CountDownLatch start = new CountDownLatch(1);
                List<Future<Boolean>> results = new ArrayList<>();
                for (int caller = 0; caller < callers; caller++)
                {
                    results.add(executor.submit(() -> {
                        ready.countDown();
                        start.await();
                        return limiter.shouldReport("same", 1_000L);
                    }));
                }
                ready.await();
                start.countDown();

                int reports = 0;
                for (Future<Boolean> result : results)
                {
                    if (result.get()) reports++;
                }
                assertEquals(
                    "concurrent reports in round " + round,
                    1,
                    reports);
            }
        }
        finally
        {
            executor.shutdownNow();
        }
    }
}

