        controller.pollIfDue();
        settings.allowNetworkAccess();
        controller.networkAccessChanged();
        server.enqueue(relayResponse(6, validV4Payload(), "\"6\""));

        controller.pollIfDue();
        assertEquals("/r/" + INITIAL_CODE, takeRelay().getPath());
        waitFor(() -> clientTasks.size() == 1);
