import net.runelite.api.MenuEntry;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

@RunWith(Parameterized.class)
public class GuardedActionFactoryTravelDestinationIsolationTest
{
    private final GuardedActionFactory factory = new GuardedActionFactory();
    private final Client client = mock(Client.class);
    private final String option;
    private final String target;
    private final GuardedAction.Kind kind;
    private final CanonicalChunk destination;

    public GuardedActionFactoryTravelDestinationIsolationTest(String name,
        String option, String target, GuardedAction.Kind kind,
        CanonicalChunk destination)
    {
        this.option = option;
        this.target = target;
        this.kind = kind;
        this.destination = destination;
    }

    @Parameterized.Parameters(name = "{0}")
    public static Collection<Object[]> cases()
    {
        return Arrays.asList(new Object[][] {
            unknown("lunar-isle", "Teleport", "Lunar Isle"),
            unknown("zanaris", "Travel", "Fairy ring — Zanaris"),
            unknown("prifddinas", "Travel", "Spirit tree — Prifddinas"),
            unknown("lovakengj", "Travel", "Mine cart — Lovakengj"),
            unknown("nardah", "Pay-fare", "Magic carpet to Nardah"),
            unknown("taverley", "Travel", "Balloon — Taverley"),
            unknown("eagles-peak", "Travel", "Eagle — Eagles' Peak"),
            unknown("nightmare-zone", "Minigame teleport", "Nightmare Zone"),
            unknown("hunter-guild", "Travel", "Quetzal — Hunter Guild"),
            known("port-khazard-existing-legacy-match", "Charter", "Port Khazard", 41, 49)
        });
    }

    @Test
    public void preservesThePreTaskSevenLegacyClassification()
    {
        MenuEntry entry = mock(MenuEntry.class);
        when(entry.getOption()).thenReturn(option);
        when(entry.getTarget()).thenReturn(target);
        when(entry.getType()).thenReturn(MenuAction.UNKNOWN);
        when(entry.getItemId()).thenReturn(-1);

        GuardedAction action = factory.from(entry, client);

        assertEquals(kind, action.getKind());
        if (destination == null)
        {
            assertNull(action.getChunk());
        }
        else
        {
            assertEquals(destination, action.getChunk());
        }
    }

    private static Object[] unknown(String name, String option, String target)
    {
        return new Object[] { name, option, target, GuardedAction.Kind.UNKNOWN, null };
    }

    private static Object[] known(String name, String option, String target, int cx, int cy)
    {
        return new Object[] { name, option, target, GuardedAction.Kind.TELEPORT,
            new CanonicalChunk(cx, cy) };
    }
}

package com.fatelocked.guardian;

import com.fatelocked.CanonicalChunk;
import com.fatelocked.rules.FateRuleEngine;
import com.fatelocked.rules.PermissionStatus;
import com.fatelocked.rules.RuleDecision;
import com.fatelocked.guardian.travel.TravelAction;
import com.fatelocked.guardian.travel.TravelDecision;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class StrictModeGuardTest
{
    private final CanonicalChunk chunk = new CanonicalChunk(50, 50);
    private final StrictModeGuard guard = new StrictModeGuard();

    @Test
    public void onlyFreshCertainLockedActionsBlock()
    {
        FateRuleEngine engine = mock(FateRuleEngine.class);
        when(engine.target(any(), anyString(), anyString()))
            .thenReturn(decision(PermissionStatus.LOCKED));
        when(engine.entry(any())).thenReturn(decision(PermissionStatus.LOCKED));
        when(engine.equipment(anyInt())).thenReturn(decision(PermissionStatus.LOCKED));
        GuardContext enabled = new GuardContext(true, false, true, true, engine);
        GuardedAction npc = action(GuardedAction.Kind.NPC);

        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decide(npc, new GuardContext(false, false, true, true, engine)).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decide(npc, new GuardContext(true, true, true, true, engine)).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decide(npc, new GuardContext(true, false, false, true, engine)).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decide(npc, new GuardContext(true, false, true, false, engine)).getOutcome());
        assertEquals(GuardResult.Outcome.WARN_ONLY,
            guard.decide(action(GuardedAction.Kind.MOVEMENT), enabled).getOutcome());
        assertEquals(GuardResult.Outcome.BLOCK,
            guard.decide(npc, enabled).getOutcome());
        assertEquals(GuardResult.Outcome.BLOCK,
            guard.decide(action(GuardedAction.Kind.BANK), enabled).getOutcome());
        assertEquals(GuardResult.Outcome.BLOCK,
            guard.decide(action(GuardedAction.Kind.TELEPORT), enabled).getOutcome());
        assertEquals(GuardResult.Outcome.BLOCK,
            guard.decide(new GuardedAction(
                GuardedAction.Kind.EQUIPMENT, "wield", "whip", null, 4151),
                enabled).getOutcome());
    }

    @Test
    public void blockAlwaysImpliesLocked()
    {
        for (PermissionStatus status : PermissionStatus.values())
        {
            FateRuleEngine engine = mock(FateRuleEngine.class);
            when(engine.target(any(), anyString(), anyString()))
                .thenReturn(decision(status));
            GuardResult result = guard.decide(
                action(GuardedAction.Kind.NPC),
                new GuardContext(true, false, true, true, engine));
            if (result.getOutcome() == GuardResult.Outcome.BLOCK)
            {
                assertEquals(PermissionStatus.LOCKED,
                    result.getDecision().getStatus());
            }
            else if (status != PermissionStatus.LOCKED)
            {
                assertEquals(GuardResult.Outcome.ALLOW, result.getOutcome());
            }
        }
    }

    @Test
    public void travelBlocksOnlyFreshExactLockedDecisions()
    {
        TravelAction exact = exactTravel();
        TravelDecision locked = travelDecision(PermissionStatus.LOCKED);

        assertEquals(GuardResult.Outcome.BLOCK,
            guard.decideTravel(exact, locked, enabled()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, travelDecision(PermissionStatus.UNKNOWN),
                enabled()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, locked, disabled()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, locked, paused()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, locked, stale()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, locked, wrongAccount()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(unknownTravel(), locked, enabled()).getOutcome());
    }

    @Test
    public void travelAllowsOtherStatusesAndNullInputs()
    {
        TravelAction exact = exactTravel();
        TravelDecision locked = travelDecision(PermissionStatus.LOCKED);

        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, travelDecision(PermissionStatus.ALLOWED),
                enabled()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, travelDecision(PermissionStatus.NOT_READY),
                enabled()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(null, locked, enabled()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, null, enabled()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, locked, null).getOutcome());
    }

    @Test
    public void travelBlockAlwaysImpliesExactLockedDecision()
    {
        for (PermissionStatus status : PermissionStatus.values())
        {
            TravelAction action = exactTravel();
            GuardResult result = guard.decideTravel(
                action, travelDecision(status), enabled());

            if (result.getOutcome() == GuardResult.Outcome.BLOCK)
            {
                assertEquals(PermissionStatus.LOCKED,
                    result.getDecision().getStatus());
                assertEquals(TravelAction.Confidence.EXACT,
                    action.getConfidence());
            }
            else
            {
                assertEquals(GuardResult.Outcome.ALLOW, result.getOutcome());
            }
        }
    }

    private GuardedAction action(GuardedAction.Kind kind)
    {
        return new GuardedAction(kind, "use", "goblin", chunk, null);
    }

    private static RuleDecision decision(PermissionStatus status)
    {
        return new RuleDecision(status, "Target", null);
    }

    private static TravelAction exactTravel()
    {
        return new TravelAction(
            TravelAction.Family.WALK, "walk", "Walk here", null,
            new CanonicalChunk(51, 51), null,
            TravelAction.Confidence.EXACT);
    }

    private static TravelAction unknownTravel()
    {
        return new TravelAction(
            TravelAction.Family.UNKNOWN, "unknown", "Unknown", null,
            null, null, TravelAction.Confidence.UNKNOWN);
    }

    private static TravelDecision travelDecision(PermissionStatus status)
    {
        return new TravelDecision(status, "Destination", "not unlocked");
    }

    private static GuardContext enabled()
    {
        return new GuardContext(true, false, true, true, null);
    }

    private static GuardContext disabled()
    {
        return new GuardContext(false, false, true, true, null);
    }

    private static GuardContext paused()
    {
        return new GuardContext(true, true, true, true, null);
    }

    private static GuardContext stale()
    {
        return new GuardContext(true, false, true, false, null);
    }

    private static GuardContext wrongAccount()
    {
        return new GuardContext(true, false, false, true, null);
    }
}

package com.fatelocked.guardian;

import com.fatelocked.CanonicalChunk;
import com.fatelocked.rules.FateRuleEngine;
import com.fatelocked.rules.PermissionStatus;
import com.fatelocked.rules.RuleDecision;
import com.fatelocked.guardian.travel.TravelAction;
import com.fatelocked.guardian.travel.TravelDecision;
import net.runelite.api.events.MenuOptionClicked;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class StrictModeClickHandlerTest
{
    @Test
    public void consumesOnlyCertainLockedActions()
    {
        FateRuleEngine engine = mock(FateRuleEngine.class);
        when(engine.target(any(), anyString(), anyString()))
            .thenReturn(new RuleDecision(PermissionStatus.LOCKED, "Goblin", null));
        GuardedAction action = new GuardedAction(
            GuardedAction.Kind.NPC, "attack", "goblin",
            new CanonicalChunk(50, 50), null);
        StrictModeClickHandler handler =
            new StrictModeClickHandler(new StrictModeGuard());

        MenuOptionClicked locked = mock(MenuOptionClicked.class);
        handler.handle(locked, action,
            new GuardContext(true, false, true, true, engine));
        verify(locked).consume();

        MenuOptionClicked disabled = mock(MenuOptionClicked.class);
        handler.handle(disabled, action,
            new GuardContext(false, false, true, true, engine));
        verify(disabled, never()).consume();

        when(engine.target(any(), anyString(), anyString()))
            .thenReturn(new RuleDecision(PermissionStatus.UNKNOWN, "Goblin", null));
        MenuOptionClicked unknown = mock(MenuOptionClicked.class);
        handler.handle(unknown, action,
            new GuardContext(true, false, true, true, engine));
        verify(unknown, never()).consume();
    }

    @Test
    public void travelConsumesExactlyOnceOnlyForFreshExactLockedDecisions()
    {
        StrictModeClickHandler handler =
            new StrictModeClickHandler(new StrictModeGuard());
        TravelAction exact = exactTravel();
        TravelDecision locked = travelDecision(PermissionStatus.LOCKED);

        MenuOptionClicked lockedEvent = mock(MenuOptionClicked.class);
        handler.handleTravel(lockedEvent, exact, locked, enabled());
        verify(lockedEvent, times(1)).consume();

        assertNotConsumed(handler, exact, travelDecision(PermissionStatus.ALLOWED),
            enabled());
        assertNotConsumed(handler, exact, travelDecision(PermissionStatus.NOT_READY),
            enabled());
        assertNotConsumed(handler, exact, travelDecision(PermissionStatus.UNKNOWN),
            enabled());
        assertNotConsumed(handler, exact, locked, disabled());
        assertNotConsumed(handler, exact, locked, paused());
        assertNotConsumed(handler, exact, locked, stale());
        assertNotConsumed(handler, exact, locked, wrongAccount());
        assertNotConsumed(handler, unknownTravel(), locked, enabled());
        assertNotConsumed(handler, null, locked, enabled());
        assertNotConsumed(handler, exact, null, enabled());
        assertNotConsumed(handler, exact, locked, null);
    }

    private static void assertNotConsumed(
        StrictModeClickHandler handler,
        TravelAction action,
        TravelDecision decision,
        GuardContext context)
    {
        MenuOptionClicked event = mock(MenuOptionClicked.class);
        GuardResult result = handler.handleTravel(
            event, action, decision, context);
        assertEquals(GuardResult.Outcome.ALLOW,
            result.getOutcome());
        verify(event, never()).consume();
    }

    private static TravelAction exactTravel()
    {
        return new TravelAction(
            TravelAction.Family.WALK, "walk", "Walk here", null,
            new CanonicalChunk(51, 51), null,
            TravelAction.Confidence.EXACT);
    }

    private static TravelAction unknownTravel()
    {
        return new TravelAction(
            TravelAction.Family.UNKNOWN, "unknown", "Unknown", null,
            null, null, TravelAction.Confidence.UNKNOWN);
    }

    private static TravelDecision travelDecision(PermissionStatus status)
    {
        return new TravelDecision(status, "Destination", "not unlocked");
    }

    private static GuardContext enabled()
    {
        return new GuardContext(true, false, true, true, null);
    }

    private static GuardContext disabled()
    {
        return new GuardContext(false, false, true, true, null);
    }

    private static GuardContext paused()
    {
        return new GuardContext(true, true, true, true, null);
    }

    private static GuardContext stale()
    {
        return new GuardContext(true, false, true, false, null);
    }

    private static GuardContext wrongAccount()
    {
        return new GuardContext(true, false, false, true, null);
    }
}

package com.fatelocked.guardian;

import org.junit.Test;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

public class StrictModePauseTest
{
    @Test
    public void pausesForExactlySixtySeconds()
    {
        MutableClock clock = new MutableClock();
        StrictModePause pause = new StrictModePause(clock);
        pause.pauseFor(Duration.ofSeconds(60));
        assertEquals(60, pause.remainingSeconds());
        clock.advance(Duration.ofSeconds(17));
        assertEquals(43, pause.remainingSeconds());
        clock.advance(Duration.ofSeconds(43));
        assertFalse(pause.isPaused());
    }

    private static final class MutableClock extends Clock
    {
        private Instant now = Instant.parse("2026-07-24T10:00:00Z");

        void advance(Duration duration) { now = now.plus(duration); }
        @Override public ZoneId getZone() { return ZoneOffset.UTC; }
        @Override public Clock withZone(ZoneId zone) { return this; }
        @Override public Instant instant() { return now; }
    }
}

