import com.fatelocked.rules.RuleDecision;
import com.google.gson.Gson;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;
import org.junit.Test;
import org.mockito.MockedStatic;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.mockStatic;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class TravelGuardianCoordinatorTest
{
    private static final CanonicalChunk ORIGIN = new CanonicalChunk(50, 51);
    private static final CanonicalChunk DESTINATION = new CanonicalChunk(51, 51);

    private final Client client = mock(Client.class);
    private final TravelAvailability availability = mock(TravelAvailability.class);
    private final TravelBlockNoticeStore noticeStore = new TravelBlockNoticeStore(
        Clock.fixed(Instant.parse("2026-07-24T10:00:00Z"), ZoneOffset.UTC));
    private final TravelAlternativeFinder finder = mock(TravelAlternativeFinder.class);
    private final TravelGuardianCoordinator coordinator = new TravelGuardianCoordinator(
        new TravelActionResolver(),
        new TravelRuleEvaluator(),
        finder,
        noticeStore,
        new StrictModeClickHandler(new StrictModeGuard()));

    @Test
    public void provenLockedTravelIsConsumedAndExplainedOnce()
    {
        MenuOptionClicked click = walkClick();
        FateRuleEngine rules = rules(PermissionStatus.LOCKED);

        try (MockedStatic<WorldPoint> points = walkDestination())
        {
            TravelGuardianResult first = coordinator.handle(
                click, click.getMenuEntry(), client, ORIGIN,
                context(true, false, true, true, rules), rules, availability);
            TravelGuardianResult repeated = coordinator.handle(
                click, click.getMenuEntry(), client, ORIGIN,
                context(true, false, true, true, rules), rules, availability);

            verify(click, times(2)).consume();
            assertEquals("Travel blocked \u2014 Walk here",
                noticeStore.current().get().getHeadline());
            assertTrue(first.isWriteChat());
            assertFalse(repeated.isWriteChat());
            assertTrue(first.isWriteBlockedAudit());
            assertFalse(first.isWritePausedAudit());
        }
    }

    @Test
    public void pausedTravelIsAllowedAndMarkedOnlyForLocalAudit()
    {
        MenuOptionClicked click = walkClick();
        FateRuleEngine rules = rules(PermissionStatus.LOCKED);

        TravelGuardianResult result;
        try (MockedStatic<WorldPoint> points = walkDestination())
        {
            result = coordinator.handle(
                click, click.getMenuEntry(), client, ORIGIN,
                context(true, true, true, true, rules), rules, availability);
        }

        verify(click, never()).consume();
        assertFalse(noticeStore.current().isPresent());
        assertFalse(result.isWriteChat());
        assertFalse(result.isWriteBlockedAudit());
        assertTrue(result.isWritePausedAudit());
    }

    @Test
    public void strictModeOffLeavesTravelUnconsumedAndUnrecorded()
    {
        MenuOptionClicked click = walkClick();
        FateRuleEngine rules = rules(PermissionStatus.LOCKED);

        TravelGuardianResult result;
        try (MockedStatic<WorldPoint> points = walkDestination())
        {
            result = coordinator.handle(
                click, click.getMenuEntry(), client, ORIGIN,
                context(false, false, true, true, rules), rules, availability);
        }

        assertFailOpen(click, result);
    }

    @Test
    public void staleRulesLeaveTravelUnconsumedAndUnrecorded()
    {
        MenuOptionClicked click = walkClick();
        FateRuleEngine rules = rules(PermissionStatus.LOCKED);

        TravelGuardianResult result;
        try (MockedStatic<WorldPoint> points = walkDestination())
        {
            result = coordinator.handle(
                click, click.getMenuEntry(), client, ORIGIN,
                context(true, false, true, false, rules), rules, availability);
        }

        assertFailOpen(click, result);
    }

    @Test
    public void wrongAccountLeavesTravelUnconsumedAndUnrecorded()
    {
        MenuOptionClicked click = walkClick();
        FateRuleEngine rules = rules(PermissionStatus.LOCKED);

        TravelGuardianResult result;
        try (MockedStatic<WorldPoint> points = walkDestination())
        {
            result = coordinator.handle(
                click, click.getMenuEntry(), client, ORIGIN,
                context(true, false, false, true, rules), rules, availability);
        }

        assertFailOpen(click, result);
    }

    @Test
    public void legacyRulesLeaveTravelUnconsumedAndUnrecorded() throws Exception
    {
        MenuOptionClicked click = namedTeleportClick("Teleport", "Falador");
        FateRuleEngine legacy = new FateRuleEngine(
            fixture("bundles/v3-standard.json"), true, false);

        TravelGuardianResult result = coordinator.handle(
            click, click.getMenuEntry(), client, ORIGIN,
            context(true, false, true, true, legacy), legacy, availability);

        assertFailOpen(click, result);
    }

    @Test
    public void unknownTravelLeavesTheClickForTheGenericPath()
    {
        MenuOptionClicked click = namedTeleportClick("Continue", "");
        FateRuleEngine rules = rules(PermissionStatus.LOCKED);

        TravelGuardianResult result = coordinator.handle(
            click, click.getMenuEntry(), client, ORIGIN,
            context(true, false, true, true, rules), rules, availability);

        assertFailOpen(click, result);
        assertEquals(TravelAction.Confidence.UNKNOWN,
            result.getAction().getConfidence());
    }

    @Test
    public void genericTravelWordsWithoutADestinationStayFailOpen()
    {
        FateRuleEngine rules = rules(PermissionStatus.LOCKED);

        assertGenericTravelWordFailsOpen("Travel", rules);
        assertGenericTravelWordFailsOpen("Enter", rules);
        assertGenericTravelWordFailsOpen("Teleport", rules);
    }

    @Test
    public void mappedNonActivationActionsStayUnknownAndUnconsumed()
    {
        FateRuleEngine rules = rulesAt(
            new CanonicalChunk(50, 53), PermissionStatus.LOCKED);

        assertMappedNonActivationFailsOpen(
            "Drop", "Varrock teleport", rules);
        assertMappedNonActivationFailsOpen(
            "Examine", "Varrock teleport", rules);
        assertMappedNonActivationFailsOpen(
            "Destroy", "Varrock teleport", rules);
        assertMappedNonActivationFailsOpen(
            "Check", "Varrock teleport", rules);
        assertMappedNonActivationFailsOpen(
            "Configure", "Varrock teleport", rules);
        assertMappedNonActivationFailsOpen(
            "Cancel", "Varrock teleport", rules);
    }

    @Test
    public void notReadyDestinationLeavesTravelUnconsumedAndUnrecorded()
    {
        MenuOptionClicked click = walkClick();
        FateRuleEngine rules = rules(PermissionStatus.NOT_READY);

        TravelGuardianResult result;
        try (MockedStatic<WorldPoint> points = walkDestination())
        {
            result = coordinator.handle(
                click, click.getMenuEntry(), client, ORIGIN,
                context(true, false, true, true, rules), rules, availability);
        }

        assertFailOpen(click, result);
        assertEquals(PermissionStatus.UNKNOWN, result.getDecision().getStatus());
    }

    @Test
    public void sameChunkWalkInsideALockedChunkRemainsUnconsumedAndUnrecorded()
    {
        MenuOptionClicked click = walkClick();
        FateRuleEngine rules = rulesAt(ORIGIN, PermissionStatus.LOCKED);

        TravelGuardianResult result;
        try (MockedStatic<WorldPoint> points = walkDestination(ORIGIN))
        {
            result = coordinator.handle(
                click, click.getMenuEntry(), client, ORIGIN,
                context(true, false, true, true, rules), rules, availability);
        }

        assertFailOpen(click, result);
        assertEquals(TravelAction.Confidence.UNKNOWN,
            result.getAction().getConfidence());
        assertNull(result.getAction().getDestination());
    }

    @Test
    public void walkWithoutAKnownOriginRemainsUnconsumedAndUnrecorded()
    {
        MenuOptionClicked click = walkClick();
        FateRuleEngine rules = rules(PermissionStatus.LOCKED);

        TravelGuardianResult result;
        try (MockedStatic<WorldPoint> points = walkDestination())
        {
            result = coordinator.handle(
                click, click.getMenuEntry(), client, null,
                context(true, false, true, true, rules), rules, availability);
        }

        assertFailOpen(click, result);
        assertEquals(TravelAction.Confidence.UNKNOWN,
            result.getAction().getConfidence());
        assertNull(result.getAction().getDestination());
    }

    @Test
    public void alternativeLookupFailureNeverCancelsAProvenBlock()
    {
        MenuOptionClicked click = walkClick();
        FateRuleEngine rules = rules(PermissionStatus.LOCKED);
        when(finder.find(any(), any(), any()))
            .thenThrow(new IllegalStateException("inventory unavailable"));

        TravelGuardianResult result;
        try (MockedStatic<WorldPoint> points = walkDestination())
        {
            result = coordinator.handle(
                click, click.getMenuEntry(), client, ORIGIN,
                context(true, false, true, true, rules), rules, availability);
        }

        verify(click).consume();
        assertTrue(result.isWriteBlockedAudit());
        assertNull(result.getAlternative());
        assertNull(noticeStore.current().get().getAlternative());
    }

    private void assertFailOpen(
        MenuOptionClicked click, TravelGuardianResult result)
    {
        verify(click, never()).consume();
        assertFalse(noticeStore.current().isPresent());
        assertFalse(result.isWriteChat());
        assertFalse(result.isWriteBlockedAudit());
        assertFalse(result.isWritePausedAudit());
    }

    private MenuOptionClicked walkClick()
    {
        MenuEntry entry = mock(MenuEntry.class);
        when(entry.getOption()).thenReturn("Walk here");
        when(entry.getTarget()).thenReturn("");
        when(entry.getType()).thenReturn(MenuAction.WALK);
        when(entry.getParam0()).thenReturn(10);
        when(entry.getParam1()).thenReturn(20);
        when(client.getPlane()).thenReturn(0);
        MenuOptionClicked click = mock(MenuOptionClicked.class);
        when(click.getMenuEntry()).thenReturn(entry);
        return click;
    }

    private static MenuOptionClicked namedTeleportClick(
        String option, String target)
    {
        MenuEntry entry = mock(MenuEntry.class);
        when(entry.getOption()).thenReturn(option);
        when(entry.getTarget()).thenReturn(target);
        when(entry.getType()).thenReturn(MenuAction.UNKNOWN);
        MenuOptionClicked click = mock(MenuOptionClicked.class);
        when(click.getMenuEntry()).thenReturn(entry);
        return click;
    }

    private void assertGenericTravelWordFailsOpen(String option, FateRuleEngine rules)
    {
        MenuOptionClicked click = namedTeleportClick(option, "New destination");
        TravelGuardianResult result = coordinator.handle(
            click, click.getMenuEntry(), client, ORIGIN,
            context(true, false, true, true, rules), rules, availability);

        assertFailOpen(click, result);
        assertEquals(TravelAction.Confidence.UNKNOWN,
            result.getAction().getConfidence());
        assertNull(result.getAction().getDestination());
    }
    private void assertMappedNonActivationFailsOpen(
        String option, String target, FateRuleEngine rules)
    {
        MenuOptionClicked click = namedTeleportClick(option, target);
        TravelGuardianResult result = coordinator.handle(
            click, click.getMenuEntry(), client, ORIGIN,
            context(true, false, true, true, rules), rules, availability);

        assertFailOpen(click, result);
        assertEquals(TravelAction.Family.UNKNOWN,
            result.getAction().getFamily());
        assertEquals(TravelAction.Confidence.UNKNOWN,
            result.getAction().getConfidence());
        assertNull(result.getAction().getDestination());
    }
    private MockedStatic<WorldPoint> walkDestination()
    {
        return walkDestination(DESTINATION);
    }

    private MockedStatic<WorldPoint> walkDestination(CanonicalChunk destination)
    {
        MockedStatic<WorldPoint> points = mockStatic(WorldPoint.class);
        points.when(() -> WorldPoint.fromScene(client, 10, 20, 0))
            .thenReturn(new WorldPoint(destination.getCx() << 6,
                destination.getCy() << 6, 0));
        return points;
    }

    private static GuardContext context(
        boolean enabled,
        boolean paused,
        boolean accountMatches,
        boolean freshRules,
        FateRuleEngine rules)
    {
        return new GuardContext(
            enabled, paused, accountMatches, freshRules, rules);
    }

    private static FateRuleEngine rules(PermissionStatus status)
    {
        return rulesAt(DESTINATION, status);
    }

    private static FateRuleEngine rulesAt(
        CanonicalChunk destination, PermissionStatus status)
    {
        FateRuleEngine rules = mock(FateRuleEngine.class);
        when(rules.entry(destination)).thenReturn(
            new RuleDecision(status, "Locked destination", null));
        return rules;
    }

    private FateLockedBundle fixture(String name) throws Exception
    {
        try (InputStream in = getClass().getClassLoader().getResourceAsStream(name))
        {
            return FateLockedBundle.loadFromJson(
                new Gson(),
                new String(in.readAllBytes(), StandardCharsets.UTF_8));
        }
    }
}

package com.fatelocked.guardian.travel;

import com.fatelocked.CanonicalChunk;
import com.fatelocked.FateLockedBundle;
import com.fatelocked.rules.FateRuleEngine;
import com.fatelocked.rules.PermissionStatus;
import com.fatelocked.rules.RuleDecision;
import com.google.gson.Gson;
import org.junit.Test;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class TravelRuleEvaluatorTest
{
    private final TravelRuleEvaluator evaluator = new TravelRuleEvaluator();
    private final CanonicalChunk destination = new CanonicalChunk(50, 50);

    @Test
    public void onlyExactAuthoredLocksRemainLocked() throws Exception
    {
        TravelDecision destinationLocked = evaluator.evaluate(
            exact(null), engine("LOCKED", "[\"Fairy Rings\"]", true, false));
        assertEquals(PermissionStatus.LOCKED, destinationLocked.getStatus());
        assertEquals("Lumbridge is locked", destinationLocked.getReason());

        TravelDecision mobilityLocked = evaluator.evaluate(
            exact("Fairy Rings"), engine("ALLOWED", "[]", true, false));
        assertEquals(PermissionStatus.LOCKED, mobilityLocked.getStatus());
        assertEquals("Fairy Rings is not unlocked", mobilityLocked.getReason());

        assertEquals(PermissionStatus.ALLOWED,
            evaluator.evaluate(exact("Fairy Rings"),
                engine("ALLOWED", "[\"Fairy Rings\"]", true, false)).getStatus());
        assertEquals(PermissionStatus.UNKNOWN,
            evaluator.evaluate(unknown(),
                engine("ALLOWED", "[\"Fairy Rings\"]", true, false)).getStatus());
        assertEquals(PermissionStatus.UNKNOWN,
            evaluator.evaluate(exact("Unmapped Network"),
                engine("ALLOWED", "[\"Fairy Rings\"]", true, false)).getStatus());
    }

    @Test
    public void destinationUncertaintyTakesPrecedenceOverMobility() throws Exception
    {
        FateRuleEngine lockedMobility = engine("ALLOWED", "[]", true, false);

        assertEquals(PermissionStatus.UNKNOWN,
            evaluator.evaluate(exactAt(new CanonicalChunk(1, 1), "Fairy Rings"),
                lockedMobility).getStatus());
        assertEquals(PermissionStatus.UNKNOWN,
            evaluator.evaluate(exact("Fairy Rings"),
                engine("NOT_READY", "[]", true, false)).getStatus());
        assertEquals(PermissionStatus.LOCKED,
            evaluator.evaluate(exact("Unmapped Network"),
                engine("LOCKED", "[]", true, false)).getStatus());
    }

    @Test
    public void notReadyMobilityRemainsUnknown()
    {
        FateRuleEngine notReady = mock(FateRuleEngine.class);
        when(notReady.entry(destination)).thenReturn(
            new RuleDecision(
                PermissionStatus.ALLOWED, "Lumbridge", null));
        when(notReady.mobility("Fairy Rings")).thenReturn(
            new RuleDecision(
                PermissionStatus.NOT_READY, "Fairy Rings", null));

        assertEquals(PermissionStatus.UNKNOWN,
            evaluator.evaluate(exact("Fairy Rings"), notReady).getStatus());
    }

    @Test
    public void untrustedAndLegacyRulesNeverBecomeLocked() throws Exception    {
        assertEquals(PermissionStatus.UNKNOWN,
            evaluator.evaluate(exact(null),
                engine("LOCKED", "[]", false, false)).getStatus());
        assertEquals(PermissionStatus.UNKNOWN,
            evaluator.evaluate(exact(null),
                engine("LOCKED", "[]", true, true)).getStatus());

        FateRuleEngine legacy = new FateRuleEngine(
            fixture("bundles/v3-standard.json"), true, false);
        assertEquals(PermissionStatus.UNKNOWN,
            evaluator.evaluate(exactAt(new CanonicalChunk(46, 52), null), legacy)
                .getStatus());
    }

    @Test
    public void nullAndUnresolvedActionsRemainUnknown() throws Exception
    {
        FateRuleEngine allowed = engine(
            "ALLOWED", "[\"Fairy Rings\"]", true, false);

        assertEquals(PermissionStatus.UNKNOWN,
            evaluator.evaluate(null, allowed).getStatus());
        assertEquals(PermissionStatus.UNKNOWN,
            evaluator.evaluate(new TravelAction(
                TravelAction.Family.WALK, "walk", "Walk here", destination,
                null, null, TravelAction.Confidence.EXACT), allowed).getStatus());
        TravelDecision unknown = evaluator.evaluate(unknown(), allowed);
        assertEquals("Unknown travel", unknown.getLabel());
        assertNull(unknown.getReason());
    }

    @Test
    public void unresolvedNamedMethodsRemainUnknownEvenWhenTheDestinationWouldLock()
        throws Exception
    {
        FateRuleEngine locked = engine("LOCKED", "[\"Fairy Rings\"]", true, false);
        TravelAction unresolved = new TravelAction(
            TravelAction.Family.SPELL_OR_ITEM, "named-teleport",
            "Teleport New destination", new CanonicalChunk(49, 50), null,
            null, TravelAction.Confidence.UNKNOWN);

        assertEquals(PermissionStatus.UNKNOWN,
            evaluator.evaluate(unresolved, locked).getStatus());
    }
    private TravelAction exact(String requiredUnlock)
    {
        return exactAt(destination, requiredUnlock);
    }

    private TravelAction exactAt(CanonicalChunk chunk, String requiredUnlock)
    {
        return new TravelAction(
            TravelAction.Family.WALK, "walk", "Walk here",
            new CanonicalChunk(49, 50), chunk, requiredUnlock,
            TravelAction.Confidence.EXACT);
    }

    private TravelAction unknown()
    {
        return new TravelAction(
            TravelAction.Family.UNKNOWN, "unknown", "Unknown travel",
            new CanonicalChunk(49, 50), null, null,
            TravelAction.Confidence.UNKNOWN);
    }

    private FateRuleEngine engine(
        String entry, String mobility, boolean accountMatches, boolean stale)
        throws Exception
    {
        String json = fixtureText("bundles/v4-rules.json")
            .replace("\"entry\": \"ALLOWED\"", "\"entry\": \"" + entry + "\"")
            .replace("\"mobility\": [\"Fairy Rings\"]", "\"mobility\": " + mobility);
        return new FateRuleEngine(
            FateLockedBundle.loadFromJson(new Gson(), json), accountMatches, stale);
    }

    private FateLockedBundle fixture(String name) throws Exception
    {
        return FateLockedBundle.loadFromJson(new Gson(), fixtureText(name));
    }

    private String fixtureText(String name) throws Exception
    {
        try (InputStream in = getClass().getClassLoader().getResourceAsStream(name))
        {
            return new String(in.readAllBytes(), StandardCharsets.UTF_8);
        }
    }
}

package com.fatelocked.guardian.travel;

import org.junit.Test;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TravelBlockNoticeStoreTest
{
    @Test
    public void noticeExpiresAtTheFourSecondBoundaryAndChatDeduplicatesForTenSeconds()
    {
        MutableClock clock = new MutableClock();
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(clock);

        store.show("fairy-rings:canifis", "Travel blocked - Fairy ring to Canifis",
            "Morytania is locked", "Varrock teleport tablet");

        assertTrue(store.current().isPresent());
        assertTrue(store.shouldWriteChat("fairy-rings:canifis"));
        assertFalse(store.shouldWriteChat("fairy-rings:canifis"));

        clock.advance(Duration.ofSeconds(4));
        assertFalse(store.current().isPresent());

        clock.advance(Duration.ofSeconds(5).plusMillis(999));
        assertFalse(store.shouldWriteChat("fairy-rings:canifis"));
        clock.advance(Duration.ofMillis(1));
        assertTrue(store.shouldWriteChat("fairy-rings:canifis"));
    }

    @Test
    public void repeatedShowRefreshesOnlyTheBannerExpiry()
    {
        MutableClock clock = new MutableClock();
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(clock);

        store.show("walk:locked", "Travel blocked - Walk here", "Locked", null);
        assertTrue(store.shouldWriteChat("walk:locked"));
        clock.advance(Duration.ofSeconds(3));

        store.show("walk:locked", "Travel blocked - Walk here", "Locked", null);
        clock.advance(Duration.ofSeconds(1));
        assertTrue(store.current().isPresent());
        assertFalse(store.shouldWriteChat("walk:locked"));

        clock.advance(Duration.ofSeconds(3));
        assertFalse(store.current().isPresent());
        clock.advance(Duration.ofSeconds(3));
        assertTrue(store.shouldWriteChat("walk:locked"));
    }

    @Test
    public void chatFingerprintsAreBoundedToThirtyTwoEntries()
    {
        MutableClock clock = new MutableClock();
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(clock);

        for (int index = 0; index < 33; index++)
        {
            assertTrue(store.shouldWriteChat("fingerprint-" + index));
        }

        assertTrue(store.shouldWriteChat("fingerprint-0"));
        assertFalse(store.shouldWriteChat("fingerprint-32"));
    }

    @Test
    public void noticeIsAnImmutableSnapshotWithAnExactExpiry()
    {
        MutableClock clock = new MutableClock();
        TravelBlockNoticeStore store = new TravelBlockNoticeStore(clock);

        store.show("boat:port", "Travel blocked - Boat", "Locked", null);

        TravelBlockNotice notice = store.current().get();
        assertEquals("boat:port", notice.getFingerprint());
        assertEquals("Travel blocked - Boat", notice.getHeadline());
        assertEquals("Locked", notice.getReason());
        assertEquals(Instant.parse("2026-07-24T10:00:04Z"), notice.getExpiresAt());
    }

    private static final class MutableClock extends Clock
    {
        private Instant now = Instant.parse("2026-07-24T10:00:00Z");

        void advance(Duration duration)
        {
            now = now.plus(duration);
        }

        @Override public ZoneId getZone() { return ZoneOffset.UTC; }
        @Override public Clock withZone(ZoneId zone) { return this; }
        @Override public Instant instant() { return now; }
    }
}

package com.fatelocked.guardian.travel;

import com.fatelocked.CanonicalChunk;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import org.mockito.MockedStatic;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.mockStatic;
import static org.mockito.Mockito.when;

public class TravelActionResolverTest
{
    private final TravelActionResolver resolver = new TravelActionResolver();
    private final Client client = mock(Client.class);
    private final CanonicalChunk origin = new CanonicalChunk(50, 50);

    @Test
    public void resolvesNamedTeleportWalkAndCrossChunkObject()
    {
        assertTravel(entry("Teleport", "Falador", MenuAction.UNKNOWN),
            TravelAction.Family.SPELL_OR_ITEM, new CanonicalChunk(46, 52), true);

        MenuEntry walk = entry("Walk here", "", MenuAction.WALK);
        when(walk.getParam0()).thenReturn(10);
        when(walk.getParam1()).thenReturn(20);
        when(client.getPlane()).thenReturn(0);
        try (MockedStatic<WorldPoint> points = mockStatic(WorldPoint.class))
        {
            points.when(() -> WorldPoint.fromScene(client, 10, 20, 0))
                .thenReturn(new WorldPoint(3264, 3264, 0));
            assertTravel(walk, TravelAction.Family.WALK,
                new CanonicalChunk(51, 51), true);
        }

        MenuEntry door = entry("Open", "Gate", MenuAction.GAME_OBJECT_FIRST_OPTION);
        when(door.getParam0()).thenReturn(10);
        when(door.getParam1()).thenReturn(20);
        try (MockedStatic<WorldPoint> points = mockStatic(WorldPoint.class))
        {
            points.when(() -> WorldPoint.fromScene(client, 10, 20, 0))
                .thenReturn(new WorldPoint(3264, 3264, 0));
            assertTravel(door, TravelAction.Family.BOUNDARY_OBJECT,
                new CanonicalChunk(51, 51), true);
        }
    }

    @Test
    public void walkAndBoundaryMethodsWithoutResolvedCrossChunkTargetsStayUnknown()
    {
        assertUnknown(entry("Walk here", "", MenuAction.UNKNOWN));
        TravelAction unresolvedWalk = resolver.resolve(
            entry("Walk here", "", MenuAction.WALK), null, origin);
        assertEquals(TravelAction.Confidence.UNKNOWN, unresolvedWalk.getConfidence());
        assertNull(unresolvedWalk.getDestination());

        assertUnknown(entry("Open", "Gate", MenuAction.UNKNOWN));
        TravelAction unresolvedBoundary = resolver.resolve(
            entry("Open", "Gate", MenuAction.GAME_OBJECT_FIRST_OPTION), null, origin);
        assertEquals(TravelAction.Confidence.UNKNOWN, unresolvedBoundary.getConfidence());
        assertNull(unresolvedBoundary.getDestination());
    }
    @Test
    public void sameChunkAndOriginUnknownWalksStayUnresolved()
    {
        MenuEntry sameChunk = entry("Walk here", "", MenuAction.WALK);
        when(sameChunk.getParam0()).thenReturn(10);
        when(sameChunk.getParam1()).thenReturn(20);
        when(client.getPlane()).thenReturn(0);
        try (MockedStatic<WorldPoint> points = mockStatic(WorldPoint.class))
        {
            points.when(() -> WorldPoint.fromScene(client, 10, 20, 0))
                .thenReturn(new WorldPoint(3201, 3201, 0));
            assertUnknown(sameChunk);
        }

        MenuEntry unknownOrigin = entry("Walk here", "", MenuAction.WALK);
