    private void renderChunk(ChunkPanelViewModel view)
    {
        chunkBody.removeAll();
        if (view == null)
        {
            chunkBody.add(emptyChunk());
            chunkBody.revalidate();
            return;
        }

        JPanel header = card();
        JLabel area = new JLabel(view.getName());
        area.setForeground(Color.WHITE);
        area.setFont(area.getFont().deriveFont(Font.BOLD, 13f));
        header.add(area);
        JLabel meta = new JLabel(
            (view.getRegion() == null ? "Unknown region" : view.getRegion())
                + "  ·  " + view.getCoordinates());
        meta.setForeground(GRAY);
        meta.setFont(meta.getFont().deriveFont(10f));
        header.add(meta);
        JLabel entry = new JLabel(
            statusText(view.getEntryStatus()) + "  ·  " + view.getFreshnessLabel());
        entry.setForeground(statusColor(view.getEntryStatus()));
        entry.setFont(entry.getFont().deriveFont(Font.BOLD, 10f));
        header.add(entry);
        chunkBody.add(header);
        chunkBody.add(Box.createVerticalStrut(6));

        JPanel counts = new JPanel(new GridLayout(1, 3, 4, 0));
        counts.setOpaque(false);
        counts.setAlignmentX(Component.LEFT_ALIGNMENT);
        counts.add(chip("Can do " + view.getAllowedCount(), GREEN));
        counts.add(chip("Not ready " + view.getNotReadyCount(), AMBER));
        counts.add(chip("Locked " + view.getLockedCount(), RED));
        counts.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
        chunkBody.add(counts);

        for (ChunkPanelViewModel.CategoryView category : view.getCategories())
        {
            chunkBody.add(Box.createVerticalStrut(9));
            chunkBody.add(section(category.getTitle()));
            for (ChunkPanelViewModel.RowView row : category.getRows())
            {
                chunkBody.add(permissionRow(row));
            }
        }
        chunkBody.revalidate();
        chunkBody.repaint();
    }

    private static JPanel permissionRow(ChunkPanelViewModel.RowView row)
    {
        JPanel panel = new JPanel(new BorderLayout(5, 1));
        panel.setBackground(SURFACE);
        panel.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(0, 0, 1, 0, SEPARATOR),
            new EmptyBorder(5, 6, 5, 6)));
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);

        String shown = row.getName().length() > 28
            ? row.getName().substring(0, 27) + "…" : row.getName();
        JLabel name = new JLabel(row.getStatusGlyph() + " " + shown);
        name.setForeground(statusColor(row.getStatus()));
        name.setToolTipText(row.getDetail() == null
            ? row.getName() : row.getName() + " — " + row.getDetail());
        panel.add(name, BorderLayout.CENTER);

        if (row.getStatusText() != null)
        {
            JLabel status = new JLabel(row.getStatusText());
            status.setForeground(statusColor(row.getStatus()));
            status.setFont(status.getFont().deriveFont(10f));
            panel.add(status, BorderLayout.EAST);
        }
        if (row.getDetail() != null)
        {
            JLabel detail = new JLabel(row.getDetail());
            detail.setForeground(GRAY);
            detail.setFont(detail.getFont().deriveFont(9f));
            panel.add(detail, BorderLayout.SOUTH);
        }
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE,
            row.getDetail() == null ? 28 : 40));
        return panel;
    }

    private static JPanel emptyChunk()
    {
        JPanel panel = card();
        JLabel label = new JLabel("Enter the game to see this chunk");
        label.setForeground(GRAY);
        panel.add(label);
        return panel;
    }

    private static JPanel card()
    {
        JPanel panel = column();
        panel.setBackground(SURFACE);
        panel.setBorder(new EmptyBorder(8, 8, 8, 8));
        return panel;
    }

    private static JLabel chip(String text, Color color)
    {
        JLabel label = new JLabel(text, JLabel.CENTER);
        label.setOpaque(true);
        label.setBackground(SURFACE);
        label.setForeground(color);
        label.setFont(label.getFont().deriveFont(Font.BOLD, 9f));
        label.setBorder(new EmptyBorder(4, 2, 4, 2));
        return label;
    }

    void flashStatus(String message, boolean ok)
    {
        runOnEdt(() -> {
            importVal.setText(message);
            importVal.setForeground(ok ? GREEN : RED);
            importVal.setVisible(true);
            if (ok && bundleSection.isExpanded())
            {
                bundleSection.setExpanded(false);
            }
        });
    }

    private static boolean hasText(Component component, String text)
    {
        if (component instanceof JLabel)
        {
            String shown = ((JLabel) component).getText();
            if (shown != null && shown.contains(text))
            {
                return true;
            }
        }
        if (component instanceof java.awt.Container)
        {
            for (Component child
                : ((java.awt.Container) component).getComponents())
            {
                if (hasText(child, text))
                {
                    return true;
                }
            }
        }
        return false;
    }
    private static Color statusColor(PermissionStatus status)
    {
        if (status == PermissionStatus.ALLOWED) return GREEN;
        if (status == PermissionStatus.NOT_READY) return AMBER;
        if (status == PermissionStatus.LOCKED) return RED;
        return GRAY;
    }

    private static String statusText(PermissionStatus status)
    {
        if (status == PermissionStatus.ALLOWED) return "Available";
        if (status == PermissionStatus.NOT_READY) return "Not ready";
        if (status == PermissionStatus.LOCKED) return "Locked";
        return "Unknown";
    }

    private static JLabel title(String text)
    {
        JLabel label = new JLabel(text);
        label.setForeground(AMBER);
        label.setFont(label.getFont().deriveFont(Font.BOLD, 13f));
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        return label;
    }

    private static JLabel section(String text)
    {
        JLabel label = new JLabel(text);
        label.setForeground(GRAY);
        label.setFont(label.getFont().deriveFont(Font.BOLD, 10f));
        label.setBorder(new EmptyBorder(0, 0, 4, 0));
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        return label;
    }

    private static JPanel column()
    {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);
        return panel;
    }

    private static String headerText(String label, boolean open)
    {
        return (open ? "▾ " : "▸ ") + label;
    }

    private static JButton collapsibleHeader(String label, JPanel body, boolean open)
    {
        JButton header = new JButton(headerText(label, open));
        header.setFont(header.getFont().deriveFont(Font.BOLD, 10f));
        header.setForeground(GRAY);
        header.setContentAreaFilled(false);
        header.setBorder(new EmptyBorder(0, 0, 4, 0));
        header.setFocusPainted(false);
        header.setHorizontalAlignment(JButton.LEFT);
        header.setAlignmentX(Component.LEFT_ALIGNMENT);
        body.setVisible(open);
        header.addActionListener(event -> {
            boolean nowOpen = !body.isVisible();
            body.setVisible(nowOpen);
            header.setText(headerText(label, nowOpen));
            body.revalidate();
        });
        return header;
    }

    private static void fullWidth(JButton button)
    {
        button.setAlignmentX(Component.LEFT_ALIGNMENT);
        button.setMaximumSize(new Dimension(
            Integer.MAX_VALUE, button.getPreferredSize().height));
    }

    private static JLabel value()
    {
        JLabel label = new JLabel("—");
        label.setForeground(Color.WHITE);
        return label;
    }

    private static JPanel stats(String[] labels, JLabel[] values)
    {
        JPanel grid = new JPanel(new GridLayout(0, 2, 6, 3));
        grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
        grid.setAlignmentX(Component.LEFT_ALIGNMENT);
        for (int i = 0; i < labels.length; i++)
        {
            JLabel key = new JLabel(labels[i]);
            key.setForeground(Color.LIGHT_GRAY);
            grid.add(key);
            grid.add(values[i]);
        }
        grid.setMaximumSize(new Dimension(
            Integer.MAX_VALUE, grid.getPreferredSize().height));
        return grid;
    }

    private static String orDash(String value)
    {
        return value == null || value.trim().isEmpty() ? "—" : value;
    }
}

package com.fatelocked;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;

/**
 * In-game HUD: current keys / fate points / buff / next goal from the bundle's
 * run state, plus the player's current chunk and its lock status — the
 * always-visible version of what the side panel shows.
 */
public class FateLockedHudOverlay extends OverlayPanel
{
    private static final Color GOLD = new Color(245, 158, 11);
    private static final Color GREEN = new Color(52, 211, 153);
    private static final Color RED = new Color(248, 113, 113);
    private static final Color GRAY = new Color(156, 163, 175);

    private final Client client;
    private final FateLockedPlugin plugin;
    private final FateLockedConfig config;

    // Nearest bank/shop cache — recomputed on chunk change or bundle reload.
    private FateLockedBundle cachedBundle;
    private CanonicalChunk cachedChunk;
    private FateLockedBundle.Nearest cachedBank;
    private FateLockedBundle.Nearest cachedShop;

    @Inject
    FateLockedHudOverlay(Client client, FateLockedPlugin plugin, FateLockedConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        setResizable(false);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showHud())
        {
            return null;
        }

        FateLockedBundle bundle = plugin.getBundle();
        FateLockedBundle.RunState state = bundle.getState();

        // Fixed width so long area names ("Draynor Village · Misthalin") sit on
        // one line instead of wrapping to three.
        panelComponent.setPreferredSize(new Dimension(165, 0));
        panelComponent.getChildren().add(TitleComponent.builder()
            .text("Fate Locked")
            .color(GOLD)
            .build());

        if (state != null)
        {
            StringBuilder keyStr = new StringBuilder(String.valueOf(state.getKeys()));
            if (state.getSpecialKeys() > 0) keyStr.append(" · O").append(state.getSpecialKeys());
            if (state.getChaosKeys() > 0) keyStr.append(" · C").append(state.getChaosKeys());
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Keys")
                .right(keyStr.toString())
                .rightColor(GOLD)
                .build());
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Fate")
                .right(String.valueOf(state.getFatePoints()))
                .rightColor(Color.WHITE)
                .build());
            String buff = state.getActiveBuff();
            if (buff != null && !"NONE".equals(buff))
            {
                panelComponent.getChildren().add(LineComponent.builder()
                    .left("Buff")
                    .right(buff)
                    .rightColor("GREED".equals(buff) ? GOLD : GREEN)
                    .build());
            }
            List<String> goals = state.getPinnedGoals();
            if (goals != null && !goals.isEmpty())
            {
                panelComponent.getChildren().add(LineComponent.builder()
                    .left("Goal")
                    .right(truncate(goals.get(0), 20))
                    .rightColor(Color.WHITE)
                    .build());
            }
            String bound = state.getLinkedAccount();
            if (bound != null && !bound.trim().isEmpty())
            {
                Player me = client.getLocalPlayer();
                String current = me == null ? null : me.getName();
                boolean match = current == null
                    || FateLockedPlugin.normName(bound).equals(FateLockedPlugin.normName(current));
                panelComponent.getChildren().add(LineComponent.builder()
                    .left("Account")
                    .right(truncate(bound, 14) + (match ? "" : " ⚠"))
                    .rightColor(match ? GREEN : RED)
                    .build());
            }
        }

        Player local = client.getLocalPlayer();
        WorldPoint wp = local == null ? null : local.getWorldLocation();
        if (wp != null)
        {
            CanonicalChunk chunk = CanonicalChunk.of(wp);
            String label = bundle.labelAt(chunk);
            FateLockedBundle.LockState lock = bundle.lockStateAt(chunk);

            panelComponent.getChildren().add(LineComponent.builder()
                .left("Here")
                .right(label == null ? "(" + chunk.getCx() + ", " + chunk.getCy() + ")" : truncate(label, 22))
                .rightColor(Color.WHITE)
                .build());
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Status")
                .right(lock == FateLockedBundle.LockState.UNLOCKED ? "Unlocked"
                    : lock == FateLockedBundle.LockState.LOCKED ? "LOCKED" : "Unknown")
                .rightColor(lock == FateLockedBundle.LockState.UNLOCKED ? GREEN
                    : lock == FateLockedBundle.LockState.LOCKED ? RED : GRAY)
                .build());

            if (config.showNearest() && bundle.hasNearestData())
            {
                // Recompute only when the player crosses a chunk boundary or a
                // new bundle is imported — render() runs per frame.
                if (bundle != cachedBundle || !chunk.equals(cachedChunk))
                {
                    cachedBundle = bundle;
                    cachedChunk = chunk;
                    cachedBank = bundle.nearestUsableBank(chunk);
                    cachedShop = bundle.nearestUsableShop(chunk);
                }
                addNearestLine("Bank", cachedBank, chunk, bundle);
                addNearestLine("Shop", cachedShop, chunk, bundle);
            }
        }

        if (bundle.getTotalChunks() > 0)
        {
            int pct = (int) Math.round(100.0 * bundle.getUnlockedChunks() / bundle.getTotalChunks());
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Unlocked")
                .right(bundle.getUnlockedAreas() + "/" + bundle.getTotalAreas() + " · " + pct + "%")
                .rightColor(GOLD)
                .build());
        }

        String slayerWarn = plugin.getSlayerTaskWarn();
        if (slayerWarn != null)
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Slayer")
                .right(truncate(slayerWarn, 18) + " ⚠")
                .leftColor(RED)
                .rightColor(RED)
                .build());
        }

        String overTier = plugin.getOverTierSummary();
        if (overTier != null)
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Over-tier")
                .right(truncate(overTier, 20))
                .leftColor(RED)
                .rightColor(RED)
                .build());
        }

        return super.render(graphics);
    }

    /** One "Bank:" / "Shop:" line: "here ✓", "<Area> · <dist> <dir>", or "none unlocked". */
    private void addNearestLine(String label, FateLockedBundle.Nearest near,
                                CanonicalChunk from, FateLockedBundle bundle)
    {
        if (near == null)
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left(label)
                .right("none unlocked")
                .rightColor(RED)
                .build());
            return;
        }
        if (near.getDistanceChunks() == 0)
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left(label)
                .right("here ✓")
                .rightColor(GREEN)
                .build());
            return;
        }
        String area = bundle.labelAt(near.getChunk());
        String name = area == null
            ? "(" + near.getChunk().getCx() + ", " + near.getChunk().getCy() + ")"
            : area.split(" · ")[0];
        String dir = compass(near.getChunk().getCx() - from.getCx(),
            near.getChunk().getCy() - from.getCy());
        panelComponent.getChildren().add(LineComponent.builder()
            .left(label)
            .right(truncate(name, 13) + " · " + near.getDistanceChunks() + " " + dir)
            .rightColor(Color.WHITE)
            .build());
    }

    /** 8-way compass point for a chunk delta; a 2:1 dominant axis collapses
     *  to its cardinal (dx=+5,dy=+1 → "E"; dx=+5,dy=+4 → "NE"). World Y
     *  grows northward. Never called with dx=dy=0 (distance 0 is "here"). */
    static String compass(int dx, int dy)
    {
        String ns = dy > 0 ? "N" : "S";
        String ew = dx > 0 ? "E" : "W";
        if (dy == 0 || Math.abs(dx) >= 2 * Math.abs(dy)) return ew;
        if (dx == 0 || Math.abs(dy) >= 2 * Math.abs(dx)) return ns;
        return ns + ew;
    }

    private static String truncate(String s, int max)
    {
        return s.length() <= max ? s : s.substring(0, max - 1) + "…";
    }
}

package com.fatelocked;

import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;

/**
 * Full-viewport red border flash when the player crosses into locked
 * territory — the visual counterpart to the warning sound. The plugin sets
 * {@code flashUntil}; this overlay pulses a fading frame until it expires.
 */
public class FateLockedFlashOverlay extends Overlay
{
    private static final int FRAME_THICKNESS = 14;

    private final Client client;
    private final FateLockedPlugin plugin;
    private final FateLockedConfig config;

    @Inject
    FateLockedFlashOverlay(Client client, FateLockedPlugin plugin, FateLockedConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        if (!config.flashOnLocked())
        {
            return null;
        }
        long until = plugin.getLockedFlashUntil();
        long now = System.currentTimeMillis();
        if (now >= until)
        {
            return null;
        }

        // Fade out over the flash window, with a 4 Hz pulse on top.
        float remaining = (until - now) / (float) FateLockedPlugin.LOCKED_FLASH_MS;
        float pulse = 0.6f + 0.4f * (float) Math.abs(Math.sin(now / 125.0));
        int alpha = Math.min(255, Math.max(0, (int) (200 * remaining * pulse)));

        int w = client.getCanvasWidth();
        int h = client.getCanvasHeight();
        g.setColor(new Color(239, 68, 68, alpha));
        g.setStroke(new BasicStroke(FRAME_THICKNESS));
        g.drawRect(FRAME_THICKNESS / 2, FRAME_THICKNESS / 2, w - FRAME_THICKNESS, h - FRAME_THICKNESS);
        return null;
    }
}

package com.fatelocked.panel;

import com.fatelocked.CanonicalChunk;
import com.fatelocked.FateLockedBundle;
import com.fatelocked.rules.ChunkPermissionRow;
import com.fatelocked.rules.ChunkPermissionSnapshot;
import com.fatelocked.rules.FateRuleEngine;
import com.fatelocked.rules.PermissionStatus;
import com.fatelocked.rules.RuleDecision;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class ChunkPanelViewModelFactory
{
    private static final List<String> ORDER = Arrays.asList(
        "SKILLING", "BANKS", "SHOPS", "QUESTS", "COMBAT",
        "TRAVEL", "FARMING", "ACTIVITIES");

    private static final Map<String, String> TITLES;
    static
    {
        Map<String, String> titles = new LinkedHashMap<>();
        titles.put("SKILLING", "Skilling");
        titles.put("BANKS", "Banks");
        titles.put("SHOPS", "Shops");
        titles.put("QUESTS", "Quests");
        titles.put("COMBAT", "Combat");
        titles.put("TRAVEL", "Travel");
        titles.put("FARMING", "Farming");
        titles.put("ACTIVITIES", "Activities");
        TITLES = Collections.unmodifiableMap(titles);
    }

    public ChunkPanelViewModel create(
        FateLockedBundle bundle,
        CanonicalChunk chunk,
        boolean accountMatches,
        Instant importedAt)
    {
        RuleDecision entry = new FateRuleEngine(
            bundle, accountMatches, false).entry(chunk);
        ChunkPermissionSnapshot snapshot = accountMatches
            ? bundle.permissionsAt(chunk).orElse(null) : null;
        List<ChunkPanelViewModel.CategoryView> categories = new ArrayList<>();
        int allowed = 0;
        int notReady = 0;
        int locked = 0;
        int unknown = 0;

        if (snapshot != null)
        {
            for (String id : ORDER)
            {
                List<ChunkPermissionRow> source = snapshot.getCategories().get(id);
                if (source == null || source.isEmpty()) continue;
                List<ChunkPanelViewModel.RowView> rows = new ArrayList<>();
                for (ChunkPermissionRow row : source)
                {
                    PermissionStatus status = row.getStatus();
                    if (status == PermissionStatus.ALLOWED) allowed++;
                    else if (status == PermissionStatus.NOT_READY) notReady++;
                    else if (status == PermissionStatus.LOCKED) locked++;
                    else unknown++;
                    rows.add(new ChunkPanelViewModel.RowView(
                        row.getName(),
                        status,
                        glyph(id, status),
                        statusText(id, status),
                        keepsDetail(id) ? row.getDetail() : null));
                }
                categories.add(new ChunkPanelViewModel.CategoryView(
                    id, TITLES.get(id), rows));
            }
        }
        else if (accountMatches && bundle.isLegacyRules())
        {
            Map<String, List<String>> legacy = bundle.legacyContentAt(chunk);
            Map<String, String> legacyCategories = new LinkedHashMap<>();
            legacyCategories.put("mon", "COMBAT");
            legacyCategories.put("shop", "SHOPS");
            legacyCategories.put("farm", "FARMING");
            legacyCategories.put("poi", "ACTIVITIES");
            for (String id : ORDER)
            {
                List<ChunkPanelViewModel.RowView> rows = new ArrayList<>();
                for (Map.Entry<String, String> mapping : legacyCategories.entrySet())
                {
                    if (!id.equals(mapping.getValue())) continue;
                    for (String name : legacy.getOrDefault(
                        mapping.getKey(), Collections.emptyList()))
                    {
                        rows.add(new ChunkPanelViewModel.RowView(
                            name,
                            PermissionStatus.UNKNOWN,
                            "?",
                            statusText(id, PermissionStatus.UNKNOWN),
                            null));
                        unknown++;
                    }
                }
                if (!rows.isEmpty())
                {
                    categories.add(new ChunkPanelViewModel.CategoryView(
                        id, TITLES.get(id), rows));
                }
            }
        }

        String name = snapshot == null ? bundle.labelAt(chunk) : snapshot.getName();
        if (name == null || name.trim().isEmpty()) name = "Unknown chunk";
        String region = snapshot == null ? bundle.regionAt(chunk) : snapshot.getRegion();
        return new ChunkPanelViewModel(
            name,
            region,
            chunk.getCx() + ", " + chunk.getCy(),
            entry.getStatus(),
            freshness(importedAt),
            allowed,
            notReady,
            locked,
            unknown,
            categories);
    }

    private static boolean keepsDetail(String category)
    {
        return "SKILLING".equals(category) || "TRAVEL".equals(category);
    }

    private static String glyph(String category, PermissionStatus status)
    {
        if (status == PermissionStatus.UNKNOWN) return "?";
        if ("COMBAT".equals(category))
        {
            return status == PermissionStatus.ALLOWED ? "✓" : "✕";
        }
        if (status == PermissionStatus.ALLOWED) return "✓";
        if (status == PermissionStatus.NOT_READY) return "○";
        return "✕";
    }

    private static String statusText(String category, PermissionStatus status)
    {
        if ("QUESTS".equals(category) || "COMBAT".equals(category)) return null;
        if (status == PermissionStatus.ALLOWED) return "Available";
        if (status == PermissionStatus.NOT_READY) return "Not ready";
        if (status == PermissionStatus.LOCKED) return "Locked";
        return "Unknown";
    }

    private static String freshness(Instant importedAt)
    {
        if (importedAt == null) return "Offline snapshot";
        long minutes = Math.max(0,
            Duration.between(importedAt, Instant.now()).toMinutes());
        return minutes < 1 ? "Synced now" : "Synced " + minutes + "m ago";
    }
}

package com.fatelocked.panel;

import com.fatelocked.rules.PermissionStatus;
import lombok.Getter;

import java.util.Collections;
import java.util.List;

@Getter
public final class ChunkPanelViewModel
{
    private final String name;
    private final String region;
    private final String coordinates;
    private final PermissionStatus entryStatus;
    private final String freshnessLabel;
    private final int allowedCount;
    private final int notReadyCount;
    private final int lockedCount;
    private final int unknownCount;
    private final List<CategoryView> categories;

    ChunkPanelViewModel(
        String name,
        String region,
        String coordinates,
        PermissionStatus entryStatus,
        String freshnessLabel,
        int allowedCount,
        int notReadyCount,
        int lockedCount,
        int unknownCount,
        List<CategoryView> categories)
    {
        this.name = name;
        this.region = region;
        this.coordinates = coordinates;
        this.entryStatus = entryStatus;
        this.freshnessLabel = freshnessLabel;
        this.allowedCount = allowedCount;
        this.notReadyCount = notReadyCount;
        this.lockedCount = lockedCount;
        this.unknownCount = unknownCount;
        this.categories = Collections.unmodifiableList(categories);
    }

    public CategoryView category(String id)
    {
        for (CategoryView category : categories)
        {
            if (category.getId().equals(id)) return category;
        }
        return null;
    }

    @Getter
    public static final class CategoryView
    {
        private final String id;
        private final String title;
        private final List<RowView> rows;

        CategoryView(String id, String title, List<RowView> rows)
        {
            this.id = id;
            this.title = title;
            this.rows = Collections.unmodifiableList(rows);
        }
    }

    @Getter
    public static final class RowView
    {
        private final String name;
        private final PermissionStatus status;
        private final String statusGlyph;
        private final String statusText;
        private final String detail;

        RowView(
            String name,
            PermissionStatus status,
            String statusGlyph,
            String statusText,
            String detail)
        {
            this.name = name;
            this.status = status;
            this.statusGlyph = statusGlyph;
            this.statusText = statusText;
            this.detail = detail;
        }
    }
}

package com.fatelocked;

import com.google.inject.Inject;
import net.runelite.client.config.ConfigManager;

import java.util.List;

final class TrackerConnectionSettings
{
    static final String RELAY_BASE_URL =
        "https://fate-relay.fatelocked.workers.dev";
    static final String PAIRING_CODE_KEY = "trackerPairingCode";
    private static final String CODE_PATTERN = "[0-9a-f]{32}";
    private static final String[] LEGACY_TOKEN_PREFIXES = {
        "eventToken.", "stateToken.", "suggestToken.", "ackToken."
    };

    private final ConfigManager configManager;

    @Inject
    TrackerConnectionSettings(ConfigManager configManager)
    {
        this.configManager = configManager;
    }

    String pairingCode()
    {
        String value = configManager.getConfiguration(
            FateLockedConfig.GROUP, PAIRING_CODE_KEY);
        return value != null && value.trim().matches(CODE_PATTERN)
            ? value.trim() : "";
    }

    boolean isPaired()
    {
        return !pairingCode().isEmpty();
    }

    boolean networkAccessAllowed()
    {
        // A pairing code or the retired onlineSync flag does not imply consent.
        return Boolean.parseBoolean(configManager.getConfiguration(
            FateLockedConfig.GROUP, FateLockedConfig.NETWORK_ACCESS_KEY));
    }

    void allowNetworkAccess()
    {
        configManager.setConfiguration(
            FateLockedConfig.GROUP, FateLockedConfig.NETWORK_ACCESS_KEY, "true");
    }

    void replacePairingCode(String code)
    {
        if (code == null || !code.matches(CODE_PATTERN))
        {
            throw new IllegalArgumentException("Invalid pairing code");
        }
        configManager.setConfiguration(
            FateLockedConfig.GROUP, PAIRING_CODE_KEY, code);
    }

    void clearPairing()
    {
        configManager.unsetConfiguration(
            FateLockedConfig.GROUP, PAIRING_CODE_KEY);
    }

    void clearLegacySettings()
    {
        configManager.unsetConfiguration(FateLockedConfig.GROUP, "onlineSync");
        configManager.unsetConfiguration(FateLockedConfig.GROUP, "syncCode");
        configManager.unsetConfiguration(FateLockedConfig.GROUP, "relayUrl");

        List<String> storedKeys = configManager.getConfigurationKeys(
            FateLockedConfig.GROUP + ".");
        if (storedKeys == null)
        {
            return;
        }

        String groupPrefix = FateLockedConfig.GROUP + ".";
        for (String storedKey : storedKeys)
        {
            String key = storedKey != null
                && storedKey.startsWith(groupPrefix)
                ? storedKey.substring(groupPrefix.length())
                : storedKey;
            if (hasLegacyTokenPrefix(key))
            {
                configManager.unsetConfiguration(
                    FateLockedConfig.GROUP, key);
            }
        }
    }

    private static boolean hasLegacyTokenPrefix(String key)
    {
        if (key == null)
        {
            return false;
        }
        for (String prefix : LEGACY_TOKEN_PREFIXES)
        {
            if (key.startsWith(prefix))
            {
                return true;
            }
        }
        return false;
    }

}

package com.fatelocked;

/**
 * Tracks the two independently fallible registrations used by the travel
 * banner so partial startup and shutdown can be retried safely.
 */
final class TravelGuardianOverlayLifecycle
{
    private final Runnable addOverlay;
    private final Runnable registerMouse;
    private final Runnable unregisterMouse;
    private final Runnable removeOverlay;
    private boolean overlayAdded;
    private boolean mouseRegistered;

    TravelGuardianOverlayLifecycle(
        Runnable addOverlay,
        Runnable registerMouse,
        Runnable unregisterMouse,
        Runnable removeOverlay)
    {
        this.addOverlay = addOverlay;
        this.registerMouse = registerMouse;
        this.unregisterMouse = unregisterMouse;
        this.removeOverlay = removeOverlay;
    }

    synchronized void start()
    {
        if (!overlayAdded)
        {
            overlayAdded = true;
            try
            {
                addOverlay.run();
            }
            catch (RuntimeException addFailure)
            {
                rollbackOverlay(addFailure);
                throw addFailure;
            }
        }
        if (!mouseRegistered)
        {
            mouseRegistered = true;
            try
            {
                registerMouse.run();
            }
            catch (RuntimeException registrationFailure)
            {
                rollbackMouse(registrationFailure);
                rollbackOverlay(registrationFailure);
                throw registrationFailure;
            }
        }
    }

    private void rollbackMouse(RuntimeException startupFailure)
    {
        if (!mouseRegistered) return;
        try
        {
            unregisterMouse.run();
            mouseRegistered = false;
        }
        catch (RuntimeException cleanupFailure)
        {
            startupFailure.addSuppressed(cleanupFailure);
        }
    }

    private void rollbackOverlay(RuntimeException startupFailure)
    {
        if (!overlayAdded) return;
        try
        {
            removeOverlay.run();
            overlayAdded = false;
        }
        catch (RuntimeException cleanupFailure)
        {
            startupFailure.addSuppressed(cleanupFailure);
        }
    }

    synchronized void stop()
    {
        RuntimeException failure = null;
        if (mouseRegistered)
        {
            try
            {
                unregisterMouse.run();
                mouseRegistered = false;
            }
            catch (RuntimeException ex)
            {
                failure = ex;
            }
        }
        if (overlayAdded)
        {
            try
            {
                removeOverlay.run();
                overlayAdded = false;
            }
            catch (RuntimeException ex)
            {
                if (failure == null)
                {
                    failure = ex;
                }
                else
                {
                    failure.addSuppressed(ex);
                }
            }
        }
        if (failure != null) throw failure;
    }
}

package com.fatelocked;

import java.awt.Color;

import java.awt.Dimension;
import java.awt.Font;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.JComponent;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;

final class CollapsiblePanelSection extends JPanel
{
    private final String title;
    private final JButton header = new JButton();
    private final JPanel body = new JPanel();
    private boolean expanded;

    CollapsiblePanelSection(String title, boolean expanded)
    {
        this.title = title;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setAlignmentX(JComponent.LEFT_ALIGNMENT);

        header.setFont(header.getFont().deriveFont(Font.BOLD, 10f));
        header.setForeground(Color.LIGHT_GRAY);
        header.setContentAreaFilled(false);
        header.setBorder(new EmptyBorder(0, 0, 4, 0));
        header.setFocusPainted(false);
        header.setHorizontalAlignment(JButton.LEFT);
        header.addActionListener(event -> setExpanded(!this.expanded));

        body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
        body.setBackground(ColorScheme.DARK_GRAY_COLOR);
        body.setAlignmentX(JComponent.LEFT_ALIGNMENT);
        fullWidthAndGrow(body);

        add(header);
        add(body);
        setExpanded(expanded);
    }

    JPanel body()
    {
        return body;
    }

    boolean isExpanded()
    {
        return expanded;
    }

    void setExpanded(boolean expanded)
    {
        this.expanded = expanded;
        body.setVisible(expanded);
        updateHeader();
        revalidate();
        repaint();
    }

    private void updateHeader()
    {
        header.setText((expanded ? "▼ " : "▶ ") + title);
        fullWidth(header);
    }

    JButton headerForTest()
    {
        return header;
    }

    private static void fullWidth(JComponent component)
    {
        component.setAlignmentX(JComponent.LEFT_ALIGNMENT);
        component.setMaximumSize(new Dimension(
            Integer.MAX_VALUE, component.getPreferredSize().height));
    }
    private static void fullWidthAndGrow(JComponent component)
    {
        component.setAlignmentX(JComponent.LEFT_ALIGNMENT);
        component.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
    }
}

package com.fatelocked;

import java.util.Objects;

final class RepeatedValueLimiter
{
    private final long windowMillis;
    private String lastValue;
    private long lastReportedAt;
    private boolean hasReported;

    RepeatedValueLimiter(long windowMillis)
    {
        this.windowMillis = windowMillis;
    }

    synchronized boolean shouldReport(String value, long nowMillis)
    {
        if (!hasReported
            || !Objects.equals(lastValue, value)
            || nowMillis - lastReportedAt >= windowMillis)
        {
            hasReported = true;
            lastValue = value;
            lastReportedAt = nowMillis;
            return true;
        }
        return false;
    }
}

package com.fatelocked;

import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Stroke;

/**
 * Tints the player's current chunk on the main game scene. Gives an at-a-glance
 * sense of the chunk's status (green/red/grey) matching the web app's colors.
 */
public class FateLockedSceneOverlay extends Overlay
{
    private static final Stroke STROKE = new BasicStroke(2f);
    private static final Stroke BORDER_STROKE = new BasicStroke(3.5f);

    @Inject private Client client;
    @Inject private FateLockedPlugin plugin;
    @Inject private FateLockedConfig config;

    @Inject
    FateLockedSceneOverlay()
    {
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.drawScene() && !config.highlightLockedBorders() && !config.shadeNearbyLocked()) return null;
        Player local = client.getLocalPlayer();
        if (local == null) return null;
        WorldPoint wp = local.getWorldLocation();
        if (wp == null) return null;

        FateLockedBundle bundle = plugin.getBundle();
        CanonicalChunk chunk = CanonicalChunk.of(wp);
        int plane = wp.getPlane();

        // Light shading for surrounding locked chunks goes first, under the
        // current-chunk tint and borders.
        if (config.shadeNearbyLocked())
        {
            drawSurroundingLocked(graphics, chunk, plane, bundle);
        }

        if (config.drawScene())
        {
            // Sub-area-aware: a Falador chunk reflects Falador's lock state, not
            // all of Asgarnia's.
            Color color;
            switch (bundle.lockStateAt(chunk))
            {
                case UNLOCKED: color = config.unlockedColor(); break;
                case LOCKED: color = config.lockedColor(); break;
                default: color = config.unauthoredColor(); break;
            }
            drawChunkOutline(graphics, chunk, plane, color);
        }

        if (config.highlightLockedBorders())
        {
            drawLockedBorders(graphics, chunk, plane, bundle);
        }
        return null;
    }

    /**
     * Trace a bright line along any edge of the current chunk that borders a
     * locked chunk — the "danger here" cue right where you'd cross over.
     */
    private void drawLockedBorders(Graphics2D g, CanonicalChunk chunk, int plane, FateLockedBundle bundle)
    {
        int cx = chunk.getCx();
        int cy = chunk.getCy();
        int bx = cx << 6;
        int by = cy << 6;

        Color c = config.lockedColor();
        g.setStroke(BORDER_STROKE);
        g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), 255));

        if (isLocked(bundle, cx + 1, cy)) drawEdge(g, bx + 63, by, bx + 63, by + 63, plane); // east
        if (isLocked(bundle, cx - 1, cy)) drawEdge(g, bx, by, bx, by + 63, plane);           // west
        if (isLocked(bundle, cx, cy + 1)) drawEdge(g, bx, by + 63, bx + 63, by + 63, plane); // north
        if (isLocked(bundle, cx, cy - 1)) drawEdge(g, bx, by, bx + 63, by, plane);           // south
    }

    private static boolean isLocked(FateLockedBundle bundle, int cx, int cy)
    {
        return bundle.lockStateAt(new CanonicalChunk(cx, cy)) == FateLockedBundle.LockState.LOCKED;
    }

    /**
     * Lightly tint every locked chunk overlapping the loaded scene (except the
     * one the player is standing in, which gets the full treatment elsewhere).
     */
    private void drawSurroundingLocked(Graphics2D g, CanonicalChunk current, int plane, FateLockedBundle bundle)
    {
        int baseX = client.getBaseX();
        int baseY = client.getBaseY();
        int cxMin = baseX >> 6, cxMax = (baseX + Constants.SCENE_SIZE - 1) >> 6;
        int cyMin = baseY >> 6, cyMax = (baseY + Constants.SCENE_SIZE - 1) >> 6;

        Color light = faint(config.lockedColor());
        g.setColor(light);
        for (int cx = cxMin; cx <= cxMax; cx++)
        {
            for (int cy = cyMin; cy <= cyMax; cy++)
            {
                if (cx == current.getCx() && cy == current.getCy()) continue;
                CanonicalChunk c = new CanonicalChunk(cx, cy);
                if (bundle.lockStateAt(c) != FateLockedBundle.LockState.LOCKED) continue;
                Polygon p = chunkScenePolyClamped(c, plane);
                if (p != null) g.fillPolygon(p);
            }
        }
    }

    /** Chunk outline polygon clipped to the loaded scene, so partly-visible chunks still draw. */
    private Polygon chunkScenePolyClamped(CanonicalChunk chunk, int plane)
    {
        int minX = client.getBaseX(), minY = client.getBaseY();
        int maxX = minX + Constants.SCENE_SIZE - 1, maxY = minY + Constants.SCENE_SIZE - 1;
        int x0 = Math.max(chunk.getCx() << 6, minX);
        int y0 = Math.max(chunk.getCy() << 6, minY);
        int x1 = Math.min((chunk.getCx() << 6) + 63, maxX);
        int y1 = Math.min((chunk.getCy() << 6) + 63, maxY);
        if (x0 > x1 || y0 > y1) return null; // no overlap with the scene

        int[][] cs = { { x0, y0 }, { x1, y0 }, { x1, y1 }, { x0, y1 } };
        Polygon p = new Polygon();
        for (int[] c : cs)
        {
            LocalPoint lp = LocalPoint.fromWorld(client, c[0], c[1]);
            if (lp == null) return null;
            Point cv = Perspective.localToCanvas(client, lp, plane);
            if (cv == null) return null;
            p.addPoint(cv.getX(), cv.getY());
        }
        return p;
    }

    /** A faint version of a color for subtle background shading. */
    private static Color faint(Color c)
    {
        return new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.max(20, Math.min(c.getAlpha(), 110) / 3));
    }

    private void drawEdge(Graphics2D g, int x0, int y0, int x1, int y1, int plane)
    {
        LocalPoint a = LocalPoint.fromWorld(client, x0, y0);
        LocalPoint b = LocalPoint.fromWorld(client, x1, y1);
        if (a == null || b == null) return; // edge off-scene
        Point ca = Perspective.localToCanvas(client, a, plane);
        Point cb = Perspective.localToCanvas(client, b, plane);
        if (ca == null || cb == null) return;
        g.drawLine(ca.getX(), ca.getY(), cb.getX(), cb.getY());
    }

    private void drawChunkOutline(Graphics2D g, CanonicalChunk chunk, int plane, Color color)
    {
        int baseX = chunk.getCx() << 6;
        int baseY = chunk.getCy() << 6;

        // Build a polygon around the chunk's perimeter — draw the four corner
        // tiles and let Perspective do the projection.
        LocalPoint[] corners = new LocalPoint[] {
            LocalPoint.fromWorld(client, baseX, baseY),
            LocalPoint.fromWorld(client, baseX + 63, baseY),
            LocalPoint.fromWorld(client, baseX + 63, baseY + 63),
            LocalPoint.fromWorld(client, baseX, baseY + 63)
        };

        Polygon p = new Polygon();
        for (LocalPoint lp : corners)
        {
            if (lp == null) return; // chunk is off-scene
            Point canvas = Perspective.localToCanvas(client, lp, plane);
            if (canvas == null) return;
            p.addPoint(canvas.getX(), canvas.getY());
        }

        g.setStroke(STROKE);
        g.setColor(color);
        g.fillPolygon(p);
        g.setColor(new Color(
            Math.min(color.getRed() + 30, 255),
            Math.min(color.getGreen() + 30, 255),
            Math.min(color.getBlue() + 30, 255),
            220));
        g.drawPolygon(p);
    }
}

