package com.fatelocked;

import com.google.gson.Gson;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

import java.io.IOException;
import java.time.Clock;
import java.time.Instant;
import java.util.function.Consumer;

final class TrackerConnectionController
{
    static final long CONNECTED_POLL_SECONDS = 60;
    static final long WAITING_POLL_SECONDS = 5;
    static final long FAILURE_BACKOFF_SECONDS = 30;
    static final long MAX_FAILURE_BACKOFF_SECONDS = 15 * 60;

    interface RelayBundleImporter
    {
        boolean importBundle(String payload);
    }

    private final OkHttpClient http;
    private final Gson gson;
    private final TrackerConnectionSettings settings;
    private final Clock clock;
    private final Consumer<Runnable> clientDispatcher;
    private final RelayBundleImporter importer;
    private final Consumer<TrackerConnectionSnapshot> listener;
    private final Object pollLock = new Object();

    private long generation;
    private RelayPollToken activePoll;
    private String acceptedVersion;
    private Instant lastSync;
    private Instant nextAutomaticPoll = Instant.EPOCH;
    private int consecutiveFailures;
    private String currentIdentityCode;
    private boolean stopped;
    private volatile TrackerConnectionSnapshot snapshot =
        TrackerConnectionSnapshot.disconnected();

    TrackerConnectionController(
        OkHttpClient http,
        Gson gson,
        TrackerConnectionSettings settings,
        Clock clock,
        Consumer<Runnable> clientDispatcher,
        RelayBundleImporter importer,
        Consumer<TrackerConnectionSnapshot> listener)
    {
        this.http = http;
        this.gson = gson;
        this.settings = settings;
        this.clock = clock;
        this.clientDispatcher = clientDispatcher;
        this.importer = importer;
        this.listener = listener;
        this.currentIdentityCode = settings.pairingCode();
        listener.accept(snapshot);
    }

    String beginPairing()
    {
        if (!settings.networkAccessAllowed())
        {
            throw new IllegalStateException("Online sync requires consent");
        }
        String code = PairingSupport.newCode();
        synchronized (pollLock)
        {
            settings.replacePairingCode(code);
            settings.clearLegacySettings();
            generation++;
            activePoll = null;
            acceptedVersion = null;
            lastSync = null;
            resetAutomaticPollingLocked();
            currentIdentityCode = code;
            stopped = false;
            snapshot = TrackerConnectionSnapshot.waiting();
            listener.accept(snapshot);
        }
        return PairingSupport.trackerPairingUrl(code);
    }

    void reportBrowserLaunchFailure()
    {
        publish(TrackerConnectionState.OFFLINE,
            "Could not open the web tracker");
    }

    void poll()
    {
        if (!settings.networkAccessAllowed())
        {
            networkAccessChanged();
            return;
        }
        String code = settings.pairingCode();
        String version;
        boolean clearLegacy = false;
        synchronized (pollLock)
        {
            if (stopped) return;
            boolean identityChanged =
                !equal(code, currentIdentityCode);
            if (identityChanged)
            {
                generation++;
                activePoll = null;
                acceptedVersion = null;
                lastSync = null;
                resetAutomaticPollingLocked();
                currentIdentityCode = code;
                snapshot = code.isEmpty()
                    ? TrackerConnectionSnapshot.disconnected()
                    : TrackerConnectionSnapshot.waiting();
                clearLegacy = !code.isEmpty();
                listener.accept(snapshot);
            }
            if (code.isEmpty())
            {
                nextAutomaticPoll = clock.instant()
                    .plusSeconds(CONNECTED_POLL_SECONDS);
                if (!identityChanged)
                {
                    snapshot = TrackerConnectionSnapshot.disconnected();
                    listener.accept(snapshot);
                }
                return;
            }
            version = acceptedVersion;
        }
        if (clearLegacy)
        {
            settings.clearLegacySettings();
        }
        RelayPollToken token = beginPoll(code, version);
        if (token == null)
        {
            return;
        }

        Request.Builder builder = new Request.Builder()
            .url(TrackerConnectionSettings.RELAY_BASE_URL
                + "/r/" + token.code)
            .get();
        if (token.acceptedVersion != null)
        {
            builder.header("If-None-Match", token.acceptedVersion);
        }
        Request request = builder.build();
        try
        {
            http.newCall(request).enqueue(new Callback()
            {
                @Override
                public void onFailure(Call call, IOException error)
                {
                    publishIfCurrent(token,
                        TrackerConnectionState.OFFLINE,
                        "Could not reach tracker");
                    scheduleFailure(token, FAILURE_BACKOFF_SECONDS,
                        MAX_FAILURE_BACKOFF_SECONDS);
                    clearPoll(token);
                }

                @Override
                public void onResponse(Call call, Response response)
                {
                    handleResponse(token, response);
                }
            });
        }
        catch (RuntimeException error)
        {
            publishIfCurrent(token,
                TrackerConnectionState.OFFLINE,
                "Could not reach tracker");
            scheduleFailure(token, FAILURE_BACKOFF_SECONDS,
                MAX_FAILURE_BACKOFF_SECONDS);
            clearPoll(token);
        }
    }

    void pollIfDue()
    {
        if (!settings.networkAccessAllowed())
        {
            networkAccessChanged();
            return;
        }
        synchronized (pollLock)
        {
            Instant now = clock.instant();
            if (stopped || now.isBefore(nextAutomaticPoll))
            {
                return;
            }
            // Reserve the next scheduler tick while this asynchronous request
            // is in flight. Its response will replace this with the healthy or
            // failure cadence.
            nextAutomaticPoll = now.plusSeconds(WAITING_POLL_SECONDS);
        }
        poll();
    }

    void networkAccessChanged()
    {
        synchronized (pollLock)
        {
            generation++;
            activePoll = null;
            acceptedVersion = null;
            lastSync = null;
            resetAutomaticPollingLocked();
            snapshot = TrackerConnectionSnapshot.disconnected();
            listener.accept(snapshot);
        }
    }

    void stop()
    {
        synchronized (pollLock)
        {
            stopped = true;
            generation++;
            activePoll = null;
            snapshot = TrackerConnectionSnapshot.disconnected();
            listener.accept(snapshot);
        }
    }

    TrackerConnectionSnapshot snapshot()
    {
        return snapshot;
    }

    private RelayPollToken beginPoll(String code, String version)
    {
        synchronized (pollLock)
        {
            if (stopped || !settings.networkAccessAllowed() || activePoll != null
                || !code.equals(settings.pairingCode())
                || !equal(version, acceptedVersion))
            {
                return null;
            }
            RelayPollToken token = new RelayPollToken(
                generation, code, canonicalVersion(version));
            activePoll = token;
            return token;
        }
    }

    private void handleResponse(
        RelayPollToken token, Response response)
    {
        try (Response current = response)
        {
            if (!isPollCurrent(token))
            {
                clearPoll(token);
                return;
            }
            if (current.code() == 304)
            {
                handleNotModified(token, current.header("ETag"));
                return;
            }
            if (current.code() == 404)
            {
                publishIfCurrent(token,
                    TrackerConnectionState.EXPIRED,
                    "Pairing request expired");
                if (token.acceptedVersion == null)
                {
                    scheduleFailure(token, WAITING_POLL_SECONDS,
                        CONNECTED_POLL_SECONDS);
                }
                else
                {
                    scheduleHealthyPoll(token);
                }
                clearPoll(token);
                return;
            }
            if (!current.isSuccessful() || current.body() == null)
            {
                boolean rateLimited = current.code() == 429;
                publishIfCurrent(token,
                    TrackerConnectionState.OFFLINE,
                    rateLimited
                        ? "Tracker relay is busy; retrying later"
                        : "Tracker is unavailable");
                long retryAfter = rateLimited
                    ? retryAfterSeconds(current.header("Retry-After")) : 0;
                scheduleFailure(token,
                    Math.max(FAILURE_BACKOFF_SECONDS, retryAfter),
                    MAX_FAILURE_BACKOFF_SECONDS);
                clearPoll(token);
                return;
            }

            RelayEnvelope envelope = gson.fromJson(
                current.body().string(), RelayEnvelope.class);
            if (envelope == null || envelope.payload == null)
            {
                scheduleFailure(token, FAILURE_BACKOFF_SECONDS,
                    MAX_FAILURE_BACKOFF_SECONDS);
                clearPoll(token);
                return;
            }
            Integer responseVersion = acceptableVersion(
                token, current.header("ETag"), envelope.version);
            if (responseVersion == null)
            {
                scheduleFailure(token, FAILURE_BACKOFF_SECONDS,
                    MAX_FAILURE_BACKOFF_SECONDS);
                clearPoll(token);
                return;
            }
            if (!isPollCurrent(token))
            {
                clearPoll(token);
                return;
            }
            String canonical = String.valueOf(responseVersion);
            if (publishIfCurrent(token,
                TrackerConnectionState.IMPORTING,
                "Importing tracker data"))
            {
                dispatchImport(
                    token, envelope.payload, canonical);
            }
        }
        catch (Exception error)
        {
            scheduleFailure(token, FAILURE_BACKOFF_SECONDS,
                MAX_FAILURE_BACKOFF_SECONDS);
            clearPoll(token);
        }
    }

    private void handleNotModified(
        RelayPollToken token, String responseEtag)
    {
        String responseVersion = responseEtag == null
            ? token.acceptedVersion
            : canonicalVersion(responseEtag);
        if (token.acceptedVersion == null
            || !token.acceptedVersion.equals(responseVersion))
        {
            clearPoll(token);
            return;
        }
        try
        {
            clientDispatcher.accept(() -> {
                try
                {
                    if (!isPollCurrent(token)
                        || !acceptedStateUnchanged(token))
                    {
                        return;
                    }
                    Instant refreshedAt = clock.instant();
                    synchronized (pollLock)
                    {
                        if (!isPollCurrentLocked(token)
                            || !acceptedStateUnchangedLocked(token))
                        {
                            return;
                        }
                        lastSync = refreshedAt;
                        scheduleHealthyPollLocked();
                        snapshot = TrackerConnectionSnapshot.connected(
                            refreshedAt, acceptedVersion);
                        listener.accept(snapshot);
                    }
                }
                finally
                {
                    clearPoll(token);
                }
            });
        }
        catch (RuntimeException error)
        {
            clearPoll(token);
        }
    }

    private void dispatchImport(
        RelayPollToken token,
        String payload,
        String version)
    {
        try
        {
            clientDispatcher.accept(() -> {
                try
                {
                    if (!isPollCurrent(token)
                        || !acceptedStateUnchanged(token))
                    {
                        return;
                    }
                    boolean imported;
                    try
                    {
                        imported = importer.importBundle(payload);
                    }
                    catch (RuntimeException error)
                    {
                        imported = false;
                    }
                    if (!imported)
                    {
                        publishIfCurrent(token,
                            TrackerConnectionState.IMPORT_FAILED,
                            "Could not import tracker data");
                        scheduleFailure(token, FAILURE_BACKOFF_SECONDS,
                            MAX_FAILURE_BACKOFF_SECONDS);
                        return;
                    }

                    Instant acceptedAt = clock.instant();
                    synchronized (pollLock)
                    {
                        if (!isPollCurrentLocked(token)
                            || !acceptedStateUnchangedLocked(token))
                        {
                            return;
                        }
                        acceptedVersion = version;
                        lastSync = acceptedAt;
                        scheduleHealthyPollLocked();
                        snapshot = TrackerConnectionSnapshot.connected(
                            acceptedAt, version);
                        listener.accept(snapshot);
                    }
                }
                finally
                {
                    clearPoll(token);
                }
            });
        }
        catch (RuntimeException error)
        {
            publishIfCurrent(token,
                TrackerConnectionState.IMPORT_FAILED,
                "Could not import tracker data");
            scheduleFailure(token, FAILURE_BACKOFF_SECONDS,
                MAX_FAILURE_BACKOFF_SECONDS);
            clearPoll(token);
        }
    }

    private void resetAutomaticPollingLocked()
    {
        consecutiveFailures = 0;
        nextAutomaticPoll = Instant.EPOCH;
    }

    private void scheduleHealthyPoll(RelayPollToken token)
    {
        synchronized (pollLock)
        {
            if (isPollCurrentLocked(token))
            {
                scheduleHealthyPollLocked();
            }
        }
    }

    private void scheduleHealthyPollLocked()
    {
        consecutiveFailures = 0;
        nextAutomaticPoll = clock.instant()
            .plusSeconds(CONNECTED_POLL_SECONDS);
    }

    private void scheduleFailure(
        RelayPollToken token, long minimumSeconds, long maximumSeconds)
    {
        synchronized (pollLock)
        {
            if (!isPollCurrentLocked(token))
            {
                return;
            }
            int shift = Math.min(consecutiveFailures, 5);
            long delay = minimumSeconds * (1L << shift);
            consecutiveFailures++;
            nextAutomaticPoll = clock.instant().plusSeconds(
                Math.min(delay, maximumSeconds));
        }
    }

    private static long retryAfterSeconds(String raw)
    {
        if (raw == null || !raw.trim().matches("[0-9]+"))
        {
            return 0;
        }
        try
        {
            return Long.parseLong(raw.trim());
        }
        catch (NumberFormatException error)
        {
            return 0;
        }
    }

    private Integer acceptableVersion(
        RelayPollToken token, String responseEtag, int bodyVersion)
    {
        Integer responseVersion = responseEtag == null
            ? Integer.valueOf(bodyVersion)
            : parseVersion(responseEtag);
        if (bodyVersion <= 0
            || responseVersion == null
            || responseVersion != bodyVersion)
        {
            return null;
        }
        if (token.acceptedVersion == null)
        {
            return responseVersion;
        }
        Integer previous = parseVersion(token.acceptedVersion);
        return previous != null && responseVersion > previous
            ? responseVersion : null;
    }

    private static Integer parseVersion(String raw)
    {
        if (raw == null) return null;
        String value = raw.trim();
        if (value.startsWith("W/"))
        {
            value = value.substring(2);
        }
        if (value.startsWith("\""))
        {
            if (value.length() < 2 || !value.endsWith("\""))
            {
                return null;
            }
            value = value.substring(1, value.length() - 1);
        }
        else if (value.contains("\""))
        {
            return null;
        }
        if (!value.matches("[1-9][0-9]*")) return null;
        try
        {
            return Integer.valueOf(value);
        }
        catch (NumberFormatException error)
        {
            return null;
        }
    }

    private static String canonicalVersion(String raw)
    {
        Integer parsed = parseVersion(raw);
        return parsed == null ? raw : String.valueOf(parsed);
    }

    private boolean isPollCurrent(RelayPollToken token)
    {
        synchronized (pollLock)
        {
            return isPollCurrentLocked(token)
                && acceptedStateUnchangedLocked(token);
        }
    }

    private boolean isPollCurrentLocked(RelayPollToken token)
    {
        return !stopped
            && settings.networkAccessAllowed()
            && token != null
            && activePoll == token
            && token.generation == generation
            && token.code.equals(settings.pairingCode());
    }

    private boolean acceptedStateUnchanged(RelayPollToken token)
    {
        synchronized (pollLock)
        {
            return acceptedStateUnchangedLocked(token);
        }
    }

    private boolean acceptedStateUnchangedLocked(RelayPollToken token)
    {
        return equal(token.acceptedVersion,
            canonicalVersion(acceptedVersion));
    }

    private void clearPoll(RelayPollToken token)
    {
        synchronized (pollLock)
        {
            if (activePoll == token)
            {
                activePoll = null;
            }
        }
    }

    private boolean publishIfCurrent(
        RelayPollToken token,
        TrackerConnectionState state,
        String explicitMessage)
    {
        synchronized (pollLock)
        {
            if (!isPollCurrentLocked(token)
                || !acceptedStateUnchangedLocked(token))
            {
                return false;
            }
            snapshot = snapshotForLocked(state, explicitMessage);
            listener.accept(snapshot);
            return true;
        }
    }

    private void publish(
        TrackerConnectionState state, String explicitMessage)
    {
        synchronized (pollLock)
        {
            snapshot = snapshotForLocked(state, explicitMessage);
            listener.accept(snapshot);
        }
    }

    private TrackerConnectionSnapshot snapshotForLocked(
        TrackerConnectionState state, String explicitMessage)
    {
        if (state == TrackerConnectionState.DISCONNECTED)
        {
            return TrackerConnectionSnapshot.disconnected();
        }
        else if (state == TrackerConnectionState.WAITING)
        {
            return TrackerConnectionSnapshot.waiting();
        }
        else if (state == TrackerConnectionState.CONNECTED)
        {
            return TrackerConnectionSnapshot.connected(
                lastSync, acceptedVersion);
        }
        else
        {
            return TrackerConnectionSnapshot.of(
                state, lastSync, acceptedVersion,
                explicitMessage == null
                    ? defaultMessage(state) : explicitMessage);
        }
    }

    private static String defaultMessage(TrackerConnectionState state)
    {
        switch (state)
        {
            case PREPARING:
                return "Preparing connection";
            case IMPORTING:
                return "Importing tracker data";
            case EXPIRED:
                return "Pairing request expired";
            case OFFLINE:
                return "Tracker is offline";
            case IMPORT_FAILED:
                return "Could not import tracker data";
            default:
                return "";
        }
    }

    private static boolean equal(String left, String right)
    {
        return left == null ? right == null : left.equals(right);
    }

    private static final class RelayPollToken
    {
        private final long generation;
        private final String code;
        private final String acceptedVersion;

        private RelayPollToken(
            long generation,
            String code,
            String acceptedVersion)
        {
            this.generation = generation;
            this.code = code;
            this.acceptedVersion = acceptedVersion;
        }
    }

    private static final class RelayEnvelope
    {
        private int version;
        private String payload;
    }
}

package com.fatelocked;

import java.time.Instant;

final class TrackerConnectionSnapshot
{
    private final TrackerConnectionState state;
    private final Instant lastSync;
    private final String acceptedVersion;
    private final String message;

    private TrackerConnectionSnapshot(
        TrackerConnectionState state,
        Instant lastSync,
        String acceptedVersion,
        String message)
    {
        this.state = state;
        this.lastSync = lastSync;
        this.acceptedVersion = acceptedVersion;
        this.message = message;
    }

    TrackerConnectionState getState()
    {
        return state;
    }

    Instant getLastSync()
    {
        return lastSync;
    }

    String getAcceptedVersion()
    {
        return acceptedVersion;
    }

    String getMessage()
    {
        return message;
    }

    static TrackerConnectionSnapshot disconnected()
    {
        return new TrackerConnectionSnapshot(
            TrackerConnectionState.DISCONNECTED,
            null, null, "Not connected");
    }

    static TrackerConnectionSnapshot waiting()
    {
        return new TrackerConnectionSnapshot(
            TrackerConnectionState.WAITING,
            null, null, "Waiting for tracker");
    }

    static TrackerConnectionSnapshot connected(
        Instant at, String version)
    {
        return new TrackerConnectionSnapshot(
            TrackerConnectionState.CONNECTED,
            at, version, "Connected");
    }

    static TrackerConnectionSnapshot of(
        TrackerConnectionState state,
        Instant lastSync,
        String acceptedVersion,
        String message)
    {
        return new TrackerConnectionSnapshot(
            state, lastSync, acceptedVersion, message);
    }
}

package com.fatelocked;

import com.fatelocked.guardian.travel.TravelBlockNotice;
import com.fatelocked.guardian.travel.TravelBlockNoticeStore;
import net.runelite.client.input.MouseListener;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.util.Optional;
import java.util.function.BooleanSupplier;

/** A transient, non-gameplay explanation for a Strict Mode travel block. */
public class FateLockedTravelBlockOverlay extends Overlay implements MouseListener
{
    private static final Color PANEL = new Color(17, 24, 39, 235);
    private static final Color HEADLINE = new Color(239, 68, 68);
    private static final Color TEXT = new Color(255, 255, 255);
    private static final Color AMBER = new Color(245, 158, 11);
    private static final String PAUSE_LABEL = "Pause Guardian for 60s";
    private static final int PADDING = 10;
    private static final int LINE_GAP = 5;
    private static final int BUTTON_HORIZONTAL_PADDING = 8;
    private static final int BUTTON_VERTICAL_PADDING = 5;

    private final Object interactionLock = new Object();
    private final TravelBlockNoticeStore noticeStore;
    private final BooleanSupplier strictModeEnabled;
    private final BooleanSupplier strictModePaused;
    private volatile InteractionState interactionState;

    public FateLockedTravelBlockOverlay(
        TravelBlockNoticeStore noticeStore,
        BooleanSupplier strictModeEnabled,
        BooleanSupplier strictModePaused,
        Runnable pauseGuardian)
    {
        if (noticeStore == null || strictModeEnabled == null || strictModePaused == null)
        {
            throw new IllegalArgumentException("notice store and Strict Mode state are required");
        }
        if (pauseGuardian == null)
        {
            throw new IllegalArgumentException("pause callback is required");
        }
        this.noticeStore = noticeStore;
        this.strictModeEnabled = strictModeEnabled;
        this.strictModePaused = strictModePaused;
        interactionState = InteractionState.hidden(pauseGuardian);
        setPosition(OverlayPosition.TOP_CENTER);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setResizable(false);
    }

    public void setPauseGuardian(Runnable pauseGuardian)
    {
        if (pauseGuardian == null)
        {
            throw new IllegalArgumentException("pause callback is required");
        }
        synchronized (interactionLock)
        {
            interactionState = interactionState.withPauseGuardian(pauseGuardian);
        }
    }

    public Rectangle getPauseButtonBounds()
    {
        Rectangle bounds = interactionState.localButtonBounds;
        return bounds == null ? null : new Rectangle(bounds);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!strictModeEnabled.getAsBoolean() || strictModePaused.getAsBoolean())
        {
            clearInteractionState();
            return null;
        }

        Optional<TravelBlockNotice> current = noticeStore.current();
        if (!current.isPresent())
        {
            clearInteractionState();
            return null;
        }

        TravelBlockNotice notice = current.get();
        String alternative = notice.getAlternative();
        if (alternative != null && alternative.trim().isEmpty())
        {
            alternative = null;
        }
        String alternativeLine = alternative == null ? null
            : "Nearest legal option: " + alternative;
        FontMetrics metrics = graphics.getFontMetrics();
        int lineHeight = metrics.getHeight();
        int buttonWidth = metrics.stringWidth(PAUSE_LABEL) + BUTTON_HORIZONTAL_PADDING * 2;
        int width = Math.max(buttonWidth, Math.max(metrics.stringWidth(notice.getHeadline()),
            Math.max(metrics.stringWidth(notice.getReason()),
                alternativeLine == null ? 0 : metrics.stringWidth(alternativeLine))))
            + PADDING * 2;
        int textLines = alternativeLine == null ? 2 : 3;
        int buttonHeight = lineHeight + BUTTON_VERTICAL_PADDING * 2;
        int height = PADDING * 2 + textLines * lineHeight
            + (textLines - 1) * LINE_GAP + LINE_GAP + buttonHeight;

        graphics.setColor(PANEL);
        graphics.fillRect(0, 0, width, height);

        int baseline = PADDING + metrics.getAscent();
        graphics.setColor(HEADLINE);
        graphics.drawString(notice.getHeadline(), PADDING, baseline);
        baseline += lineHeight + LINE_GAP;
        graphics.setColor(TEXT);
        graphics.drawString(notice.getReason(), PADDING, baseline);
        if (alternativeLine != null)
        {
            baseline += lineHeight + LINE_GAP;
            graphics.setColor(AMBER);
            graphics.drawString(alternativeLine, PADDING, baseline);
        }

        int buttonY = height - PADDING - buttonHeight;
        Rectangle localButtonBounds = new Rectangle(PADDING, buttonY, buttonWidth, buttonHeight);
        Rectangle canvasButtonBounds = new Rectangle(localButtonBounds);
        Rectangle overlayBounds = getBounds();
        canvasButtonBounds.translate(overlayBounds.x, overlayBounds.y);
        publishInteractionState(localButtonBounds, canvasButtonBounds);
        graphics.setColor(AMBER);
        graphics.fillRect(localButtonBounds.x, localButtonBounds.y,
            localButtonBounds.width, localButtonBounds.height);
        graphics.setColor(PANEL);
        graphics.drawString(PAUSE_LABEL, localButtonBounds.x + BUTTON_HORIZONTAL_PADDING,
            localButtonBounds.y + BUTTON_VERTICAL_PADDING + metrics.getAscent());
        return new Dimension(width, height);
    }

    @Override
    public MouseEvent mousePressed(MouseEvent event)
    {
        Runnable pause = null;
        synchronized (interactionLock)
        {
            InteractionState snapshot = interactionState;
            if (event.getButton() == MouseEvent.BUTTON1
                && strictModeEnabled.getAsBoolean()
                && !strictModePaused.getAsBoolean()
                && noticeStore.current().isPresent()
                && snapshot.canvasButtonBounds != null
                && snapshot.canvasButtonBounds.contains(event.getPoint()))
            {
                pause = snapshot.pauseGuardian;
            }
        }
        if (pause != null)
        {
            pause.run();
            return null;
        }
        return event;
    }

    @Override public MouseEvent mouseClicked(MouseEvent event) { return event; }
    @Override public MouseEvent mouseReleased(MouseEvent event) { return event; }
    @Override public MouseEvent mouseEntered(MouseEvent event) { return event; }
    @Override public MouseEvent mouseExited(MouseEvent event) { return event; }
    @Override public MouseEvent mouseDragged(MouseEvent event) { return event; }
    @Override public MouseEvent mouseMoved(MouseEvent event) { return event; }

    private void clearInteractionState()
    {
        synchronized (interactionLock)
        {
            interactionState = InteractionState.hidden(interactionState.pauseGuardian);
        }
    }

    private void publishInteractionState(Rectangle localButtonBounds, Rectangle canvasButtonBounds)
    {
        synchronized (interactionLock)
        {
            interactionState = new InteractionState(localButtonBounds, canvasButtonBounds,
                interactionState.pauseGuardian);
        }
    }

    private static final class InteractionState
    {
        private final Rectangle localButtonBounds;
        private final Rectangle canvasButtonBounds;
        private final Runnable pauseGuardian;

        private InteractionState(
            Rectangle localButtonBounds, Rectangle canvasButtonBounds, Runnable pauseGuardian)
        {
            this.localButtonBounds = localButtonBounds == null ? null : new Rectangle(localButtonBounds);
            this.canvasButtonBounds = canvasButtonBounds == null ? null : new Rectangle(canvasButtonBounds);
            this.pauseGuardian = pauseGuardian;
        }

        private static InteractionState hidden(Runnable pauseGuardian)
        {
            return new InteractionState(null, null, pauseGuardian);
        }

        private InteractionState withPauseGuardian(Runnable pauseGuardian)
        {
            return new InteractionState(localButtonBounds, canvasButtonBounds, pauseGuardian);
        }
    }
}

package com.fatelocked;

import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/**
 * A 64-tile chunk in canonical OSRS worldspace — i.e. the same {@code cx=x>>6,
 * cy=y>>6} that RuneLite produces. The web app stores chunks in a translated
 * space; {@link FateLockedBundle} normalizes everything to this class so
 * downstream code never has to think about the offset.
 */
@Value
public class CanonicalChunk
{
    int cx;
    int cy;

    public static CanonicalChunk of(WorldPoint wp)
    {
        return new CanonicalChunk(wp.getX() >> 6, wp.getY() >> 6);
    }

    /** South-west corner tile of this chunk, plane 0. */
    public WorldPoint southWestTile()
    {
        return new WorldPoint(cx << 6, cy << 6, 0);
    }

    /** North-east corner tile of this chunk, plane 0. */
    public WorldPoint northEastTile()
    {
        return new WorldPoint((cx << 6) + 63, (cy << 6) + 63, 0);
    }
}

package com.fatelocked;

import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.RenderOverview;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.geom.Rectangle2D;
import java.util.Map;
import java.util.Set;

/**
 * Draws tinted rectangles on the world map widget for every authored chunk:
 * green for chunks in an unlocked region, red for locked, grey for unauthored
 * (only when the camera is zoomed close enough that an unauthored overlay isn't
 * visually overwhelming).
 *
 * The render math mirrors RuneLite's built-in WorldMapOverlay — we translate
 * world tile coords to world-map viewport pixels via RenderOverview's zoom
 * level and the centre of the currently-displayed map tile.
 */
public class FateLockedWorldMapOverlay extends Overlay
{
    private static final BasicStroke BORDER = new BasicStroke(1f);

    @Inject private Client client;
    @Inject private FateLockedPlugin plugin;
    @Inject private FateLockedConfig config;
    @Inject private TooltipManager tooltipManager;

    @Inject
    FateLockedWorldMapOverlay()
    {
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(OverlayPriority.LOW);
        setLayer(OverlayLayer.MANUAL);
        drawAfterInterface(InterfaceID.WORLD_MAP);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.drawWorldMap()) return null;
        FateLockedBundle bundle = plugin.getBundle();
        if (bundle.getRegionChunks().isEmpty()) return null;

        Widget worldMap = client.getWidget(ComponentID.WORLD_MAP_MAPVIEW);
        if (worldMap == null) return null;
        RenderOverview ro = client.getRenderOverview();
        if (ro == null) return null;

        Rectangle bounds = worldMap.getBounds();
        if (bounds == null) return null;

        Shape prevClip = graphics.getClip();
        graphics.setClip(bounds);
        graphics.setStroke(BORDER);

        // Clipping region on the world map
        Area clip = new Area(bounds);

        for (Map.Entry<String, Set<CanonicalChunk>> entry : bundle.getRegionChunks().entrySet())
        {
            for (CanonicalChunk chunk : entry.getValue())
            {
                // Sub-area-aware per-chunk colouring (Falador vs the rest of
                // Asgarnia), matching the web app's map exactly.
                Color fill = bundle.lockStateAt(chunk) == FateLockedBundle.LockState.UNLOCKED
                    ? config.unlockedColor()
                    : bundle.isFrontierChunk(chunk) ? config.frontierColor() : config.lockedColor();
                Rectangle2D rect = worldMapRectForChunk(chunk, bounds, ro);
                if (rect == null) continue;
                if (!clip.intersects(rect)) continue;

                graphics.setColor(fill);
                graphics.fill(rect);
                graphics.setColor(fill.darker());
                graphics.draw(rect);
            }
        }

        if (config.worldMapTooltip())
        {
            addHoverTooltip(bundle, bounds, ro);
        }

        graphics.setClip(prevClip);
        return null;
    }

    /** Show the area name + lock status for the authored chunk under the cursor. */
    private void addHoverTooltip(FateLockedBundle bundle, Rectangle bounds, RenderOverview ro)
    {
        Point mouse = client.getMouseCanvasPosition();
        if (mouse == null || !bounds.contains(mouse.getX(), mouse.getY())) return;

        float pixelsPerTile = ro.getWorldMapZoom();
        if (pixelsPerTile <= 0) return;
        Point centre = ro.getWorldMapPosition();
        if (centre == null) return;

        // Invert worldMapRectForChunk: pixel → world tile → chunk.
        double tileX = centre.getX() + (mouse.getX() - bounds.getCenterX()) / pixelsPerTile;
        double tileY = centre.getY() - (mouse.getY() - bounds.getCenterY()) / pixelsPerTile;
        CanonicalChunk hovered = new CanonicalChunk(
            ((int) Math.floor(tileX)) >> 6, ((int) Math.floor(tileY)) >> 6);

        String label = bundle.labelAt(hovered);
        if (label == null) return; // unauthored — nothing to say

        String status = bundle.lockStateAt(hovered) == FateLockedBundle.LockState.UNLOCKED
            ? "<col=2ee59d>Unlocked</col>"
            : bundle.isFrontierChunk(hovered)
                ? "<col=f59e0b>Locked — rollable next</col>" : "<col=ef4444>Locked</col>";
        StringBuilder tip = new StringBuilder(label).append("</br>").append(status);
        if (config.worldMapTooltipContent())
        {
            // Per-chunk "what's here" from the app's chunk-content dataset —
            // capped per category so dense chunks stay a tooltip, not a page.
            for (String line : bundle.contentAt(hovered, 4))
            {
                tip.append("</br><col=a8a8a8>").append(line).append("</col>");
            }
        }
        tooltipManager.add(new Tooltip(tip.toString()));
    }

    /**
     * Translate a canonical chunk into world-map pixel coordinates inside the
     * world-map widget's bounds.
     */
    private Rectangle2D worldMapRectForChunk(CanonicalChunk chunk, Rectangle bounds, RenderOverview ro)
    {
        float pixelsPerTile = ro.getWorldMapZoom();
        // RuneLite's RenderOverview.getWorldMapPosition() returns a Point whose
        // (x, y) are world-tile coordinates of the map centre (not a WorldPoint).
        Point centre = ro.getWorldMapPosition();
        if (centre == null) return null;

        // The world-map widget shows a rectangular view of world tiles, centered
        // on `centre`. For a tile at world (tx, ty), its x-pixel on the widget is:
        //   px = widget.centerX + (tx - centre.x) * pixelsPerTile
        // y-axis is flipped (increasing y = northward in world, upward on screen):
        //   py = widget.centerY - (ty - centre.y) * pixelsPerTile
        double cx = bounds.getCenterX();
        double cy = bounds.getCenterY();

        int tileX = chunk.getCx() << 6;
        int tileY = chunk.getCy() << 6;

        double x0 = cx + (tileX - centre.getX()) * pixelsPerTile;
        double y1 = cy - (tileY - centre.getY()) * pixelsPerTile;
        double x1 = cx + (tileX + 64 - centre.getX()) * pixelsPerTile;
        double y0 = cy - (tileY + 64 - centre.getY()) * pixelsPerTile;

        return new Rectangle2D.Double(x0, y0, x1 - x0, y1 - y0);
    }
}

