        p("draynor manor", 48, 52);
        p("mind altar", 46, 54);
        p("salve graveyard", 53, 54);
        p("fenkenstrain", 55, 55);
        p("west ardougne", 39, 51);
        p("harmony island", 59, 44);
        p("cemetery", 46, 58);
        p("barrows", 55, 51);
        p("battlefront", 21, 58);

        // Ancient
        p("senntisten", 51, 52);
        p("kharyrll", 54, 54);
        p("canifis", 54, 54);
        p("lassar", 46, 54);
        p("dareeyak", 46, 57);
        p("carrallangar", 49, 57);
        p("annakarl", 51, 60);
        p("ghorrock", 46, 60);

        // Lunar
        p("moonclan", 32, 61);
        p("ourania", 38, 50);
        p("waterbirth", 39, 58);
        p("barbarian", 39, 55);
        p("khazard", 41, 49);
        p("fishing guild", 40, 53);
        p("catherby", 43, 53);
        p("ice plateau", 46, 61);

        // Jewellery — amulet of glory
        p("edgeville", 48, 54);
        p("karamja", 45, 49);
        p("draynor village", 48, 50);
        p("al kharid", 51, 49);
        // Ring of dueling
        p("castle wars", 38, 48);
        p("duel arena", 51, 50);
        p("pvp arena", 51, 50);
        p("emir's arena", 51, 50);
        p("ferox enclave", 49, 56);
        // Games necklace
        p("burthorpe", 45, 55);
        p("barbarian outpost", 39, 55);
        p("wintertodt", 25, 61);
        p("tournament", 34, 44);
        p("soul wars", 34, 44);
        // Combat bracelet
        p("warriors' guild", 45, 55);
        p("champions' guild", 49, 52);
        p("monastery", 47, 54);
        p("ranging guild", 41, 53);
        // Skills necklace
        p("crafting guild", 45, 51);
        p("cooking guild", 49, 53);
        p("woodcutting guild", 25, 54);
        p("farming guild", 19, 58);
        p("mining guild", 47, 52);
        // Ring of wealth
        p("miscellania", 39, 60);
        p("grand exchange", 49, 54);
        p("falador park", 46, 52);
        // Necklace of passage
        p("wizards' tower", 48, 49);
        p("the outpost", 37, 52);
        p("eagles' eyrie", 53, 49);
        // Burning amulet (wilderness)
        p("chaos temple", 50, 56);
