package com.fatelocked.rules;

import com.google.gson.JsonElement;
import com.google.gson.annotations.SerializedName;
import lombok.AccessLevel;
import lombok.Getter;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

@Getter
public final class RuneliteRulesManifest
{
    private String rulesVersion;
    private int contentVersion;
    private int detectorContractVersion;
    private String runId;
    private long runRevision;
    private String account;
    private String gameModeId;
    private String exportedAt;
    private boolean bankLocks;
    @Getter(AccessLevel.NONE)
    @SerializedName("knownMobility")
    private JsonElement knownMobilityDeclaration;
    private transient List<String> knownMobility;
    private Unlocks unlocks;
    private Map<String, ItemRule> itemRules;
    private Map<String, ChunkPermissionSnapshot> chunks;

    public RuneliteRulesManifest normalized()
    {
        RuneliteRulesManifest copy = new RuneliteRulesManifest();
        copy.rulesVersion = rulesVersion;
        copy.contentVersion = Math.max(0, contentVersion);
        copy.detectorContractVersion = Math.max(0, detectorContractVersion);
        copy.runId = runId;
        copy.runRevision = Math.max(0, runRevision);
        copy.account = account;
        copy.gameModeId = gameModeId;
        copy.exportedAt = exportedAt;
        copy.bankLocks = bankLocks;
        copy.knownMobility = knownMobility == null
            ? immutableStringList(knownMobilityDeclaration)
            : Unlocks.immutableList(knownMobility);
        copy.unlocks = unlocks == null ? new Unlocks().normalized() : unlocks.normalized();
        Map<String, ItemRule> normalizedItems = new TreeMap<>();
        if (itemRules != null)
        {
            for (Map.Entry<String, ItemRule> entry : itemRules.entrySet())
            {
                if (entry.getValue() != null)
                {
                    normalizedItems.put(entry.getKey(), entry.getValue().normalized());
                }
            }
        }
        copy.itemRules = Collections.unmodifiableMap(normalizedItems);

        Map<String, ChunkPermissionSnapshot> normalizedChunks = new LinkedHashMap<>();
        if (chunks != null)
        {
            for (Map.Entry<String, ChunkPermissionSnapshot> entry :
                new TreeMap<>(chunks).entrySet())
            {
                if (entry.getValue() != null)
                {
                    normalizedChunks.put(entry.getKey(),
                        entry.getValue().normalized(entry.getKey()));
                }
            }
        }
        copy.chunks = Collections.unmodifiableMap(normalizedChunks);
        return copy;
    }

    private static List<String> immutableStringList(JsonElement declaration)
    {
        if (declaration == null || !declaration.isJsonArray())
        {
            return Collections.emptyList();
        }
        List<String> values = new ArrayList<>();
        for (JsonElement value : declaration.getAsJsonArray())
        {
            if (value == null || !value.isJsonPrimitive()
                || !value.getAsJsonPrimitive().isString())
            {
                return Collections.emptyList();
            }
            values.add(value.getAsString());
        }
        return Collections.unmodifiableList(values);
    }

    public boolean hasRequiredFields()
    {
        return rulesVersion != null && !rulesVersion.trim().isEmpty()
            && runId != null && !runId.trim().isEmpty()
            && gameModeId != null && !gameModeId.trim().isEmpty()
            && exportedAt != null && !exportedAt.trim().isEmpty()
            && unlocks != null && chunks != null;
    }

    @Getter
    public static final class ItemRule
    {
        private int tier;
        private String slot;

        private ItemRule normalized()
        {
            ItemRule copy = new ItemRule();
            copy.tier = Math.max(0, tier);
            copy.slot = slot;
            return copy;
        }
    }
    @Getter
    public static final class Unlocks
    {
        private List<String> regions;
        private List<String> chunks;
        private Map<String, Integer> skills;
        private Map<String, Integer> levels;
        private Map<String, Integer> equipment;
        private List<String> banks;
        private List<String> merchants;
        private List<String> bosses;
        private List<String> minigames;
        private List<String> mobility;
        private List<String> arcana;
        private List<String> guilds;
        private List<String> farming;
        private List<String> slayer;
        private List<String> quests;

        private Unlocks normalized()
        {
            Unlocks copy = new Unlocks();
            copy.regions = immutableList(regions);
            copy.chunks = immutableList(chunks);
            copy.skills = immutableMap(skills);
            copy.levels = immutableMap(levels);
            copy.equipment = immutableMap(equipment);
            copy.banks = immutableList(banks);
            copy.merchants = immutableList(merchants);
            copy.bosses = immutableList(bosses);
            copy.minigames = immutableList(minigames);
            copy.mobility = immutableList(mobility);
            copy.arcana = immutableList(arcana);
            copy.guilds = immutableList(guilds);
            copy.farming = immutableList(farming);
            copy.slayer = immutableList(slayer);
            copy.quests = immutableList(quests);
            return copy;
        }

        private static List<String> immutableList(List<String> values)
        {
            return values == null
                ? Collections.emptyList()
                : Collections.unmodifiableList(new ArrayList<>(values));
        }

        private static Map<String, Integer> immutableMap(Map<String, Integer> values)
        {
            return values == null
                ? Collections.emptyMap()
                : Collections.unmodifiableMap(new TreeMap<>(values));
        }
    }
}

package com.fatelocked.rules;

public enum PermissionStatus
{
    ALLOWED,
    NOT_READY,
    LOCKED,
    UNKNOWN
}

package com.fatelocked.rules;

import com.fatelocked.CanonicalChunk;
import com.fatelocked.FateLockedBundle;

import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;

/**
 * Lookup-only access to the app-authored v4 rules. Unknown data always stays
 * Unknown; this layer never invents a lock from missing mappings.
 */
public class FateRuleEngine
{
    private final FateLockedBundle bundle;
    private final boolean accountMatches;
    private final boolean staleImport;

    public FateRuleEngine(
        FateLockedBundle bundle,
        boolean accountMatches,
        boolean staleImport)
    {
        this.bundle = bundle;
        this.accountMatches = accountMatches;
        this.staleImport = staleImport;
    }

    public RuleDecision entry(CanonicalChunk chunk)
    {
        RuleDecision trust = trustDecision();
        if (trust != null) return trust;
        Optional<ChunkPermissionSnapshot> snapshot = bundle.permissionsAt(chunk);
        if (!snapshot.isPresent()) return unknown(null);
        ChunkPermissionSnapshot value = snapshot.get();
        return new RuleDecision(
            value.getEntry(),
            value.getName() == null ? value.getChunkKey() : value.getName(),
            null);
    }

    public RuleDecision target(
        CanonicalChunk chunk,
        String targetKind,
        String targetName)
    {
        RuleDecision trust = trustDecision();
        if (trust != null) return trust;
        Optional<ChunkPermissionSnapshot> optional = bundle.permissionsAt(chunk);
        if (!optional.isPresent()) return unknown(targetName);
        ChunkPermissionSnapshot snapshot = optional.get();
        String kind = normalize(targetKind);
        String name = normalize(targetName);

        for (Map.Entry<String, List<ChunkPermissionRow>> category :
            snapshot.getCategories().entrySet())
        {
            for (ChunkPermissionRow row : category.getValue())
            {
                boolean kindMatches = kind.isEmpty()
                    || kind.equals(normalize(row.getTargetKind()));
                boolean nameMatches = name.isEmpty()
                    || name.equals(normalize(row.getName()));
                if (!kindMatches || !nameMatches) continue;
                PermissionStatus status = snapshot.getEntry() == PermissionStatus.LOCKED
                    ? PermissionStatus.LOCKED : row.getStatus();
                return new RuleDecision(status, row.getName(), row.getDetail());
            }
        }
        return unknown(targetName);
    }

    public RuleDecision mobility(String name)
    {
        RuleDecision trust = trustDecision();
        if (trust != null) return trust;
        if (name == null || !contains(
            bundle.getRules().getKnownMobility(), name))
        {
            return unknown(name);
        }
        PermissionStatus status = contains(
            bundle.getRules().getUnlocks().getMobility(), name)
            ? PermissionStatus.ALLOWED : PermissionStatus.LOCKED;
        return new RuleDecision(status, name,
            status == PermissionStatus.LOCKED
                ? name + " is not unlocked" : null);
    }

    public String areaLabel(CanonicalChunk chunk)
    {
        if (chunk == null || trustDecision() != null) return null;
        return bundle.permissionsAt(chunk)
            .map(ChunkPermissionSnapshot::getName)
            .orElse(null);
    }

    public RuleDecision equipment(int itemId)
    {
        RuleDecision trust = trustDecision();
        if (trust != null) return trust;
        RuneliteRulesManifest.ItemRule item = bundle.getRules()
            .getItemRules().get(String.valueOf(itemId));
        if (item == null || item.getSlot() == null || item.getSlot().trim().isEmpty())
        {
            return unknown("Item " + itemId);
        }
        Integer unlocked = bundle.getRules().getUnlocks()
            .getEquipment().get(item.getSlot());
        if (unlocked == null) return unknown("Item " + itemId);
        PermissionStatus status = item.getTier() > unlocked
            ? PermissionStatus.LOCKED : PermissionStatus.ALLOWED;
        String reason = "T" + item.getTier() + "; " + item.getSlot()
            + " is unlocked to T" + unlocked;
        return new RuleDecision(status, "Item " + itemId, reason);
    }
    private RuleDecision trustDecision()
    {
        if (!accountMatches)
        {
            return new RuleDecision(
                PermissionStatus.UNKNOWN, "Wrong account", "Wrong account");
        }
        if (staleImport)
        {
            return new RuleDecision(
                PermissionStatus.UNKNOWN, "Rules out of date", "Rules out of date");
        }
        if (bundle == null || bundle.isLegacyRules())
        {
            return unknown(null);
        }
        return null;
    }

    private static boolean contains(List<String> values, String name)
    {
        String expected = normalizeName(name);
        if (expected.isEmpty()) return false;
        for (String value : values)
        {
            if (expected.equals(normalizeName(value))) return true;
        }
        return false;
    }

    private static String normalizeName(String value)
    {
        if (value == null) return "";
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    private static RuleDecision unknown(String label)
    {
        return new RuleDecision(
            PermissionStatus.UNKNOWN,
            label == null || label.trim().isEmpty() ? "Unknown" : label,
            null);
    }

    private static String normalize(String value)
    {
        if (value == null) return "";
        return value
            .replaceAll("<[^>]+>", "")
            .replace("(LOCKED)", "")
            .trim()
            .toLowerCase(Locale.ROOT);
    }
}

