}

package com.fatelocked.rules;

import lombok.Getter;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@Getter
public final class ChunkPermissionSnapshot
{
    private String chunkKey;
    private String name;
    private String region;
    private PermissionStatus entry;
    private Map<String, List<ChunkPermissionRow>> categories;
    private Counts counts;

    ChunkPermissionSnapshot normalized(String fallbackKey)
    {
        ChunkPermissionSnapshot copy = new ChunkPermissionSnapshot();
        copy.chunkKey = chunkKey == null ? fallbackKey : chunkKey;
        copy.name = name;
        copy.region = region;
        copy.entry = entry == null ? PermissionStatus.UNKNOWN : entry;

        Map<String, List<ChunkPermissionRow>> normalized = new LinkedHashMap<>();
        if (categories != null)
        {
            for (Map.Entry<String, List<ChunkPermissionRow>> category : categories.entrySet())
            {
                List<ChunkPermissionRow> rows = new ArrayList<>();
                if (category.getValue() != null)
                {
                    for (ChunkPermissionRow row : category.getValue())
                    {
                        if (row != null) rows.add(row.normalized());
                    }
                }
                normalized.put(category.getKey(),
                    Collections.unmodifiableList(rows));
            }
        }
        copy.categories = Collections.unmodifiableMap(normalized);
        copy.counts = counts == null ? new Counts() : counts.normalized();
        return copy;
    }

    @Getter
    public static final class Counts
    {
        private int allowed;
        private int notReady;
        private int locked;
        private int unknown;

        private Counts normalized()
        {
            Counts copy = new Counts();
            copy.allowed = Math.max(0, allowed);
            copy.notReady = Math.max(0, notReady);
            copy.locked = Math.max(0, locked);
            copy.unknown = Math.max(0, unknown);
            return copy;
        }
    }
}

package com.fatelocked;

import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Ellipse2D;

/**
 * Tints the player's current 64-tile chunk on the minimap, color-coded by the
 * region's unlock status. Mirrors {@link FateLockedSceneOverlay} but projected
 * onto the minimap instead of the main scene.
 */
public class FateLockedMinimapOverlay extends Overlay
{
    // Local-coordinate radius within which Perspective will project a point.
    // Generous enough to cover the corners of chunks one step out from the
    // player's (for nearby-locked shading); the minimap clip discards overflow.
    private static final int PROJECTION_DISTANCE = 30000;
    private static final BasicStroke STROKE = new BasicStroke(1.5f);

    // The minimap draw area widget differs between the fixed and resizable
    // layouts; whichever is currently shown is the non-hidden one. ComponentID
    // is the stable modern API (WidgetInfo was removed).
    private static final int[] MINIMAP_DRAW_AREAS = {
        ComponentID.FIXED_VIEWPORT_MINIMAP_DRAW_AREA,
        ComponentID.RESIZABLE_VIEWPORT_MINIMAP_DRAW_AREA,
        ComponentID.RESIZABLE_VIEWPORT_BOTTOM_LINE_MINIMAP_DRAW_AREA,
    };

    @Inject private Client client;
    @Inject private FateLockedPlugin plugin;
    @Inject private FateLockedConfig config;

    @Inject
    FateLockedMinimapOverlay()
    {
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.drawMinimap()) return null;
        Player local = client.getLocalPlayer();
        if (local == null) return null;
        WorldPoint wp = local.getWorldLocation();
        if (wp == null) return null;

        FateLockedBundle bundle = plugin.getBundle();
        CanonicalChunk chunk = CanonicalChunk.of(wp);
        // Sub-area-aware: a Falador chunk reflects Falador's lock state, not
        // all of Asgarnia's.
        Color color;
        switch (bundle.lockStateAt(chunk))
        {
            case UNLOCKED: color = config.unlockedColor(); break;
            case LOCKED: color = config.lockedColor(); break;
            default: color = config.unauthoredColor(); break;
        }

        Polygon poly = chunkMinimapPolygon(chunk);

        // A whole 64-tile chunk projects to a polygon much larger than the
        // minimap circle, so clip to the minimap draw area before filling —
        // otherwise the tint spills across the rest of the UI.
        Shape oldClip = graphics.getClip();
        Shape clip = minimapClip();
        if (clip != null) graphics.clip(clip);

        // Faint shading for surrounding locked chunks first, beneath the current.
        if (config.shadeNearbyLocked())
        {
            drawSurroundingLocked(graphics, chunk, bundle);
        }

        if (poly != null)
        {
            graphics.setColor(color);
            graphics.fillPolygon(poly);
            graphics.setStroke(STROKE);
            graphics.setColor(new Color(
                Math.min(color.getRed() + 40, 255),
                Math.min(color.getGreen() + 40, 255),
                Math.min(color.getBlue() + 40, 255),
                230));
            graphics.drawPolygon(poly);
        }

        graphics.setClip(oldClip);
        return null;
    }

    /** Lightly tint locked chunks overlapping the loaded scene around the player. */
    private void drawSurroundingLocked(Graphics2D graphics, CanonicalChunk current, FateLockedBundle bundle)
    {
        int baseX = client.getBaseX();
        int baseY = client.getBaseY();
        int cxMin = baseX >> 6, cxMax = (baseX + Constants.SCENE_SIZE - 1) >> 6;
        int cyMin = baseY >> 6, cyMax = (baseY + Constants.SCENE_SIZE - 1) >> 6;

        Color c = config.lockedColor();
        graphics.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(),
            Math.max(20, Math.min(c.getAlpha(), 110) / 3)));
        for (int cx = cxMin; cx <= cxMax; cx++)
        {
            for (int cy = cyMin; cy <= cyMax; cy++)
            {
                if (cx == current.getCx() && cy == current.getCy()) continue;
                CanonicalChunk ch = new CanonicalChunk(cx, cy);
                if (bundle.lockStateAt(ch) != FateLockedBundle.LockState.LOCKED) continue;
                Polygon p = chunkMinimapPolygon(ch);
                if (p != null) graphics.fillPolygon(p);
            }
        }
    }

    /** Elliptical clip matching the currently-visible minimap draw area, or null. */
    private Shape minimapClip()
    {
        for (int componentId : MINIMAP_DRAW_AREAS)
        {
            Widget w = client.getWidget(componentId);
            if (w == null || w.isHidden()) continue;
            Rectangle b = w.getBounds();
            if (b != null && b.width > 0 && b.height > 0)
            {
                return new Ellipse2D.Double(b.x, b.y, b.width, b.height);
            }
        }
        return null;
    }

    /**
     * Project a chunk's four corner tiles onto the minimap. Corner local points
     * are built directly from the scene base so they project even when the
     * corner tile lies outside the loaded scene.
     */
    private Polygon chunkMinimapPolygon(CanonicalChunk chunk)
    {
        int baseX = client.getBaseX();
        int baseY = client.getBaseY();

        int x0 = chunk.getCx() << 6;
        int y0 = chunk.getCy() << 6;
        int[][] corners = {
            { x0,        y0        },
            { x0 + 64,   y0        },
            { x0 + 64,   y0 + 64   },
            { x0,        y0 + 64   },
        };

        Polygon poly = new Polygon();
        for (int[] c : corners)
        {
            LocalPoint lp = new LocalPoint((c[0] - baseX) * 128, (c[1] - baseY) * 128);
            Point mm = Perspective.localToMinimap(client, lp, PROJECTION_DISTANCE);
            if (mm == null) return null; // corner out of projection range
            poly.addPoint(mm.getX(), mm.getY());
        }
        return poly;
    }
}

package com.fatelocked;

import com.fatelocked.panel.ChunkPanelViewModel;
import com.fatelocked.rules.PermissionStatus;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;

/** Optional draggable compact twin of the category-first side panel. */
public class FateLockedContentOverlay extends OverlayPanel
{
    private static final Color AMBER = new Color(245, 158, 11);
    private static final Color GREEN = new Color(16, 185, 129);
    private static final Color RED = new Color(239, 68, 68);
    private static final Color GRAY = new Color(156, 163, 175);
    private static final Color WHITE = new Color(229, 231, 235);

    private final Client client;
    private final FateLockedPlugin plugin;
    private final FateLockedConfig config;

    @Inject
    FateLockedContentOverlay(
        Client client,
        FateLockedPlugin plugin,
        FateLockedConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        setResizable(false);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showChunkContentBox()) return null;
        Player local = client.getLocalPlayer();
        WorldPoint point = local == null ? null : local.getWorldLocation();
        if (point == null) return null;

        FateLockedBundle bundle = plugin.getBundle();
        CanonicalChunk chunk = CanonicalChunk.of(point);
        ChunkPanelViewModel view = plugin.viewModelFor(bundle, chunk);
        if (view == null) return null;

        panelComponent.setPreferredSize(new Dimension(210, 0));
        panelComponent.getChildren().add(TitleComponent.builder()
            .text(view.getName())
            .color(AMBER)
            .build());
        panelComponent.getChildren().add(LineComponent.builder()
            .left((view.getRegion() == null ? "Unknown region" : view.getRegion())
                + " · " + view.getCoordinates())
            .leftColor(GRAY)
            .build());
        panelComponent.getChildren().add(LineComponent.builder()
            .left(statusText(view.getEntryStatus()) + " · " + view.getFreshnessLabel())
            .leftColor(statusColor(view.getEntryStatus()))
            .build());

        for (ChunkPanelViewModel.CategoryView category : view.getCategories())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left(category.getTitle())
                .leftColor(AMBER)
                .build());
            int visible = Math.min(5, category.getRows().size());
            for (int i = 0; i < visible; i++)
            {
                ChunkPanelViewModel.RowView row = category.getRows().get(i);
                panelComponent.getChildren().add(LineComponent.builder()
                    .left(row.getStatusGlyph() + " " + row.getName())
                    .leftColor(statusColor(row.getStatus()))
                    .build());
            }
            int more = category.getRows().size() - visible;
            if (more > 0)
            {
                panelComponent.getChildren().add(LineComponent.builder()
                    .left("+" + more + " more")
                    .leftColor(GRAY)
                    .build());
            }
        }

        if (view.getCategories().isEmpty())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left("No mapped permissions here")
                .leftColor(WHITE)
                .build());
        }
        return super.render(graphics);
    }

    private static Color statusColor(PermissionStatus status)
    {
        if (status == PermissionStatus.ALLOWED) return GREEN;
        if (status == PermissionStatus.NOT_READY) return AMBER;
        if (status == PermissionStatus.LOCKED) return RED;
        return GRAY;
    }

    private static String statusText(PermissionStatus status)
    {
        if (status == PermissionStatus.ALLOWED) return "Available";
        if (status == PermissionStatus.NOT_READY) return "Not ready";
        if (status == PermissionStatus.LOCKED) return "Locked";
        return "Unknown";
    }
}

package com.fatelocked.guardian;

import com.fatelocked.guardian.travel.TravelAction;
import com.fatelocked.guardian.travel.TravelDecision;
import net.runelite.api.events.MenuOptionClicked;

public final class StrictModeClickHandler
{
    private final StrictModeGuard guard;

    public StrictModeClickHandler(StrictModeGuard guard)
    {
        this.guard = guard;
    }

    public GuardResult handle(
        MenuOptionClicked event,
        GuardedAction action,
        GuardContext context)
    {
        GuardResult result = guard.decide(action, context);
        if (result.getOutcome() == GuardResult.Outcome.BLOCK)
        {
            event.consume();
        }
        return result;
    }

    public GuardResult handleTravel(
        MenuOptionClicked event,
        TravelAction action,
        TravelDecision decision,
        GuardContext context)
    {
        GuardResult result = guard.decideTravel(action, decision, context);
        if (result.getOutcome() == GuardResult.Outcome.BLOCK)
        {
            event.consume();
        }
        return result;
    }
}

