            .type(FateEventType.SKILL_LEVEL)
            .canonicalLabel(skill + " Level " + level)
            .confidence(EventConfidence.EXACT)
            .detectorId("skill-level-v1")
            .detectorVersion(1)
            .evidence(evidence)
            .build());
    }

    public void clear()
    {
        levels.clear();
    }
}

