package com.fatelocked;

import com.fatelocked.guardian.GuardContext;
import com.fatelocked.guardian.StrictModeAuditEntry;
import com.fatelocked.guardian.travel.TravelAction;
import com.fatelocked.guardian.travel.TravelAlternative;
import com.fatelocked.guardian.travel.TravelAvailability;
import com.fatelocked.guardian.travel.TravelGuardianCoordinator;
import com.fatelocked.guardian.travel.TravelGuardianResult;
import com.fatelocked.rules.FateRuleEngine;
import net.runelite.api.Client;
import net.runelite.api.events.MenuOptionClicked;

import java.time.Clock;

/**
 * Thin plugin boundary for coordinator routing and post-enforcement side
 * effects. It never repeats travel recognition, evaluation, or presentation.
 */
final class TravelGuardianPluginShell
{
    enum Route
    {
        EXACT_TRAVEL,
        GENERIC,
        FAIL_OPEN
    }

    @FunctionalInterface
    interface ChatSink
    {
        void write(String message);
    }

    @FunctionalInterface
    interface AuditSink
    {
        void write(StrictModeAuditEntry entry) throws Exception;
    }

    @FunctionalInterface
    interface GenericHandler
    {
        void handle(MenuOptionClicked event, GuardContext context);
    }

    @FunctionalInterface
    interface DiagnosticSink
    {
        void record(String stage, Exception error);
    }

    private final TravelGuardianCoordinator coordinator;
    private final TravelAvailability availability;
    private final ChatSink chatSink;
    private final AuditSink auditSink;
    private final GenericHandler genericHandler;
    private final DiagnosticSink diagnosticSink;
    private final Clock clock;

    TravelGuardianPluginShell(
        TravelGuardianCoordinator coordinator,
        TravelAvailability availability,
        ChatSink chatSink,
        AuditSink auditSink,
        GenericHandler genericHandler,
        DiagnosticSink diagnosticSink,
        Clock clock)
    {
        this.coordinator = coordinator;
        this.availability = availability;
        this.chatSink = chatSink;
        this.auditSink = auditSink;
        this.genericHandler = genericHandler;
        this.diagnosticSink = diagnosticSink;
        this.clock = clock;
    }

    Route handle(
        MenuOptionClicked event,
        Client client,
        CanonicalChunk origin,
        GuardContext travelContext,
        FateRuleEngine travelRules,
        GuardContext genericContext)
    {
        TravelGuardianResult result;
        try
        {
            result = coordinator.handle(
                event, event.getMenuEntry(), client, origin,
                travelContext, travelRules, availability);
        }
        catch (RuntimeException ex)
        {
            diagnose("coordinator", ex);
            return Route.FAIL_OPEN;
        }

        if (result == null)
        {
            diagnose("coordinator",
                new IllegalStateException("coordinator returned no result"));
            return Route.FAIL_OPEN;
        }

        TravelAction action = result.getAction();
        if (action == null
            || action.getConfidence() != TravelAction.Confidence.EXACT)
        {
            genericHandler.handle(event, genericContext);
            return Route.GENERIC;
        }

        if (result.isWriteChat())
        {
            try
            {
                chatSink.write(chatMessage(result));
            }
            catch (RuntimeException ex)
            {
                diagnose("chat", ex);
            }
        }
        if (result.isWriteBlockedAudit() || result.isWritePausedAudit())
        {
            try
            {
                auditSink.write(auditEntry(result));
            }
            catch (Exception ex)
            {
                diagnose("audit", ex);
            }
        }
        return Route.EXACT_TRAVEL;
    }

    private String chatMessage(TravelGuardianResult result)
    {
        String reason = result.getDecision().getReason();
        if (reason == null || reason.trim().isEmpty())
        {
            reason = "Travel is locked";
        }
        StringBuilder message = new StringBuilder()
            .append("[Fate Guardian] Blocked ")
            .append(result.getDecision().getLabel())
            .append(": ")
            .append(reason)
            .append('.');
        TravelAlternative alternative = result.getAlternative();
        if (alternative != null
            && alternative.getLabel() != null
            && !alternative.getLabel().trim().isEmpty())
        {
            message.append(" Suggested: ")
                .append(alternative.getLabel())
                .append('.');
        }
        return message.toString();
    }

    private StrictModeAuditEntry auditEntry(TravelGuardianResult result)
    {
        TravelAction action = result.getAction();
        CanonicalChunk destination = action.getDestination();
        String chunk = destination == null ? null
            : destination.getCx() + "," + destination.getCy();
        boolean paused = result.isWritePausedAudit();
        return new StrictModeAuditEntry(
            clock.millis(),
            "TRAVEL",
            result.getDecision().getLabel(),
            chunk,
            result.getDecision().getReason(),
            paused ? "ALLOWED_PAUSED" : "BLOCKED",
            paused,
            !paused && result.getAlternative() != null);
    }

    private void diagnose(String stage, Exception error)
    {
        try
        {
            diagnosticSink.record(stage, error);
        }
        catch (RuntimeException ignored)
        {
            // Diagnostics must never change fail-open or enforced outcomes.
        }
    }
}

package com.fatelocked;

import java.awt.Color;
import java.awt.Component;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JColorChooser;
import javax.swing.JComponent;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.Keybind;

final class FateLockedConfigBinder
{
    interface ColorChooser
    {
        Color choose(Component parent, String title, Color initialColor);
    }

    private final ConfigManager configManager;
    private final Consumer<String> statusSink;
    private final ColorChooser colorChooser;
    private final Map<String, Runnable> refreshers = new LinkedHashMap<>();

    FateLockedConfigBinder(ConfigManager configManager, Consumer<String> statusSink)
    {
        this(configManager, statusSink, JColorChooser::showDialog);
    }

    FateLockedConfigBinder(ConfigManager configManager, Consumer<String> statusSink,
        ColorChooser colorChooser)
    {
        this.configManager = configManager;
        this.statusSink = statusSink;
        this.colorChooser = colorChooser;
    }

    JCheckBox booleanSetting(String key, String label, BooleanSupplier current)
    {
        return booleanSetting(key, label, current, () -> true);
    }

    JCheckBox booleanSetting(String key, String label, BooleanSupplier current,
        BooleanSupplier confirmEnable)
    {
        final boolean[] confirmed = {current.getAsBoolean()};
        JCheckBox control = new JCheckBox(label, confirmed[0]);
        control.addActionListener(event -> {
            boolean selected = control.isSelected();
            if (selected && !confirmEnable.getAsBoolean())
            {
                control.setSelected(confirmed[0]);
                return;
            }
            save(key, selected, () -> confirmed[0] = selected,
                () -> control.setSelected(confirmed[0]));
        });
        refreshers.put(key, () -> {
            Boolean value = configManager.getConfiguration(
                FateLockedConfig.GROUP, key, Boolean.class);
            if (value != null)
            {
                confirmed[0] = value;
                control.setSelected(value);
            }
        });
        return control;
    }

    JComponent keybindSetting(String key, String label, Supplier<Keybind> current)
    {
        final Keybind[] confirmed = {keybindOrNotSet(current.get())};
        KeybindCaptureButton control = new KeybindCaptureButton(confirmed[0], value -> { });
        control.setToolTipText(label);
        control.setCaptureListener(value -> save(key, value,
            () -> confirmed[0] = value,
            () -> control.setKeybind(confirmed[0])));
        refreshers.put(key, () -> {
            Keybind value = configManager.getConfiguration(
                FateLockedConfig.GROUP, key, Keybind.class);
            if (value != null)
            {
                confirmed[0] = value;
                control.setKeybind(value);
            }
        });
        return control;
    }

    JComponent colorSetting(String key, String label, Supplier<Color> current)
    {
        final Color[] confirmed = {current.get()};
        JButton control = new JButton(label);
        applyColor(control, confirmed[0]);
        control.addActionListener(event -> {
            Color selected = colorChooser.choose(control, label, confirmed[0]);
            if (selected != null)
            {
                save(key, selected, () -> {
                    confirmed[0] = selected;
                    applyColor(control, selected);
                }, () -> applyColor(control, confirmed[0]));
            }
        });
        refreshers.put(key, () -> {
            Color value = configManager.getConfiguration(
                FateLockedConfig.GROUP, key, Color.class);
            if (value != null)
            {
                confirmed[0] = value;
                applyColor(control, value);
            }
        });
        return control;
    }

    void refresh(String key)
    {
        Runnable refresher = refreshers.get(key);
        if (refresher != null)
        {
            refresher.run();
        }
    }

    Set<String> keys()
    {
        return Collections.unmodifiableSet(new LinkedHashSet<>(refreshers.keySet()));
    }

    private void save(String key, Object value, Runnable confirmed, Runnable rollback)
    {
        try
        {
            configManager.setConfiguration(FateLockedConfig.GROUP, key, value);
            confirmed.run();
        }
        catch (RuntimeException error)
        {
            rollback.run();
            statusSink.accept("couldn't save setting");
        }
    }

    private static void applyColor(JButton control, Color color)
    {
        Color preview = color == null
            ? Color.BLACK
            : new Color(color.getRed(), color.getGreen(), color.getBlue());
        control.setBackground(preview);
    }

    private static Keybind keybindOrNotSet(Keybind keybind)
    {
        return keybind == null ? Keybind.NOT_SET : keybind;
    }
}
